async function loadState() {
  try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : null; } catch { return null; }
}
async function saveState(s) { try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {} }

function App() {
  const [tab, _setTab] = useState("home");
  const [tabHist, setTabHist] = useState([]);
  const backRef = useRef(null);
  const setTab = (k) => { if (k !== tab) setTabHist(h => [...h, tab]); _setTab(k); };
  const goBackTab = () => { if (backRef.current && backRef.current()) { if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); return; } if (!tabHist.length) return; const prev = tabHist[tabHist.length - 1]; setTabHist(tabHist.slice(0, -1)); _setTab(prev); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); };
  const [lang, setLang] = useState(certInitLang);
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const t = UI[lang];

  useEffect(() => {
    loadState().then(s => {
      const init = s || { progress: {}, review: [] };
      if (!init.review) init.review = [];
      if (!init.progress) init.progress = {};
      setState(init); setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };
  const record = (domId, correct, item, src) => { try { novaLogStudy(); } catch (e) {}
    setState((prev) => { const next = JSON.parse(JSON.stringify(prev)); // 同じ描画中に続けて呼ばれても（本番モードの一括採点）前の更新に積み上げる
    if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
    next.progress[domId].attempts++;
    if (correct) next.progress[domId].correct++;
    if (!next.review) next.review = [];
    if (item) {
      const norm = item;
      const key = norm.key || ((norm.ja && norm.ja.q) || "");
      if (!correct) {
        next.review = next.review.filter(r => r.key !== key);
        next.review.unshift({ key, src, d: domId, item: norm });
        if (next.review.length > 300) next.review = next.review.slice(0, 300);
      } else {
        next.review = next.review.filter(r => r.key !== key);
      }
    }
    saveState(next); return next; });
  };
  const clearReview = () => { const next = JSON.parse(JSON.stringify(state)); next.review = []; persist(next); };
  const removeReview = (key) => { const next = JSON.parse(JSON.stringify(state)); next.review = (next.review || []).filter(r => r.key !== key); persist(next); };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const TABS = [["home", t.tabs.home], ["quiz", t.tabs.quiz], ["exam", t.tabs.exam], ["case", t.tabs.case], ["review", t.tabs.review], ["diagram", t.tabs.diagram], ["compare", t.tabs.compare], ["confuse", t.tabs.confuse], ["glossary", t.tabs.glossary]];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FBFCFF", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: nvInk("#ffffff", C.deep), padding: "16px 18px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <div>
          <div style={{ fontSize: 19, fontWeight: 700 }}>{t.appTitle}</div>
          <div style={{ fontSize: 12, marginTop: 2 }}>{t.appSub}</div>
        </div>
        <div style={{ display: "inline-flex", background: "rgba(255,255,255,0.18)", borderRadius: 999, padding: 3, flexShrink: 0 }}>
          {[["ja", "日本語"], ["en", "English"]].map(([k, lbl]) => (
            <button key={k} onClick={() => setLang(k)}
              style={{ border: "none", cursor: "pointer", borderRadius: 999, padding: "6px 16px", fontSize: 13, fontWeight: 700,
                background: lang === k ? "#fff" : "transparent", color: lang === k ? nvInk(C.deep, "#ffffff") : "rgba(255,255,255,0.85)" }}>
              {lbl}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{ flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent", color: tab === k ? nvInk(C.deep, "#ffffff") : C.ink,
              fontWeight: tab === k ? 700 : 500, fontSize: 13,
              borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent" }}>
            {label}
          </button>
        ))}
      </div>
      {tabHist.length > 0 && (
        <button onClick={goBackTab}
          aria-label="Back"
          style={{ position: "fixed", right: 16, bottom: 104, zIndex: 45, border: `1.5px solid ${C.deep}`, cursor: "pointer", borderRadius: 22, padding: "9px 15px", background: "#fff", color: C.deep, fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.20)" }}>
          ← {lang === "en" ? "Back" : "戻る"}
        </button>
      )}
      {tab !== "home" && (
        <button onClick={() => { setTab("home"); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
          aria-label="Back to top"
          style={{ position: "fixed", right: 16, bottom: 60, zIndex: 45, border: "none", cursor: "pointer", borderRadius: 22, padding: "10px 15px", background: C.deep, color: nvInk("#ffffff", C.deep), fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.28)" }}>
          ↑ {lang === "en" ? "Top" : "トップへ"}
        </button>
      )}
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} lang={lang} />}
        {tab === "quiz" && <Quiz onAnswer={record} lang={lang} />}
        {tab === "exam" && <MSExamShell sets={AICX_MS_SETS} setKeys={[1, 2, 3, 4, 5]} domainSets={null} domains={DOMAINS} lang={lang} C={C} PASS={PASS} onAnswer={record} examId="aicx" saveKey="aics_study_v2:msexam_resume" />}
        {tab === "case" && <CaseStudy onAnswer={record} lang={lang} />}
        {tab === "review" && <Review state={state} onAnswer={record} clearReview={clearReview} removeReview={removeReview} lang={lang} />}
        {tab === "diagram" && <Diagrams lang={lang} />}
        {tab === "compare" && <Compare lang={lang} />}
        {tab === "confuse" && <Confuse lang={lang} />}
        {tab === "glossary" && <Glossary lang={lang} />}
      </div>
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#5a6a85" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color: color ? nvInk(color, "#ffffff", 3) : undefined }}>{value}</div>
      <div style={{ fontSize: 11, color: "#5d6c83" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

function Home({ state, lang }) {
  const t = UI[lang];
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);
  const weak = useMemo(() => DOMAINS.map(d => {
    const p = state.progress[d.id] || { correct: 0, attempts: 0 };
    const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
    return { ...d, rate, attempts: p.attempts };
  }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate), [state]);

  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={t.correctOf(totals.c, totals.a)} color={totals.rate >= PASS ? C.ok : C.primary} />
      </div>
      <Card title={t.volumeTitle}>
        <div style={{ fontSize: 12.5, color: "#475569", lineHeight: 1.7 }}>{t.volumeDesc}</div>
      </Card>
      <Card title={t.masteryTitle}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {t.domainNames[d.id]}
                </span>
                <span style={{ color: "#5a6a85" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>
      {weak.length > 0 && (
        <Card title={t.weakTitle}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {t.domainNames[d.id]} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function QuestionCard({ Q, sel, choose, next, lastBtn, lang }) {
  const t = UI[lang];
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
      <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
        {Q.d} · {t.domainNames[Q.d]}
      </div>
      <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
      {Q.o.map((opt, i) => {
        let bg = "#fff", bd = C.mid, col = C.ink;
        if (sel !== null) {
          if (i === Q.a) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; }
          else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
        }
        return (
          <button key={i} onClick={() => choose(i)} disabled={sel !== null}
            style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px",
              borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col,
              cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.4,
              fontWeight: sel !== null && i === Q.a ? 700 : 500 }}>
            <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && (i === Q.a) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
          </button>
        );
      })}
      {sel !== null && (
        <div style={{ marginTop: 12 }}>
          <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
            <strong style={{ color: nvInk(sel === Q.a ? C.ok : C.ng, C.light) }}>{sel === Q.a ? t.correct : t.incorrect}</strong>
            {t.answerIs("ABCD"[Q.a])}{Q.e}
          </div>
          <button onClick={next}
            style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
            {lastBtn}
          </button>
        </div>
      )}
    </div>
  );
}

function Quiz({ onAnswer, lang }) {
  const t = UI[lang];
  const [filter, setFilter] = useState("ALL");
  const [mode, setMode] = useState("fixed");
  const [order, setOrder] = useState([]);
  const [pos, setPos] = useState(0);
  const [history, setHistory] = useState({});
  const [stats, setStats] = useState({ c: 0, a: 0 });

  const slot = useQuizSlot("aics_study_v2:quiz_resume");
  const domDone = useDoneSet("aics_study_v2:quiz_resume:dc");
  const resumeRef = useRef(null);
  const pool = useMemo(() => {
    const idxs = filter === "ALL" ? QUIZ_BANK.map((_, i) => i) : QUIZ_BANK.map((_, i) => i).filter(i => QUIZ_BANK[i].d === filter);
    return mode === "random" ? shuffle(idxs) : idxs;
  }, [filter, mode]);

  useEffect(() => { if (resumeRef.current) { const r = resumeRef.current; resumeRef.current = null; setOrder(r.order && r.order.length ? r.order : pool); setPos(r.pos || 0); setHistory(r.history || {}); setStats(r.stats || { c: 0, a: 0 }); return; } setOrder(pool); setPos(0); setHistory({}); setStats({ c: 0, a: 0 }); }, [pool]);
  if (order.length === 0) return <div style={{ textAlign: "center", color: "#5d6c83", padding: 20 }}>{t.noQuestions}</div>;

  const qi = order[pos % order.length];
  const Q = L(QUIZ_BANK[qi], lang);
  const sel = history[pos] !== undefined ? history[pos] : null;

  const choose = (i) => {
    if (sel !== null) return;
    setHistory(h => ({ ...h, [pos]: i }));
    const correct = i === Q.a;
    setStats(s => ({ c: s.c + (correct ? 1 : 0), a: s.a + 1 }));
    onAnswer(Q.d, correct);
  };
  const next = () => setPos(p => Math.min(order.length, p + 1));
  const prev = () => setPos(p => Math.max(0, p - 1));
  const rate = stats.a ? Math.round((stats.c / stats.a) * 100) : 0;

  // 全問回答後の結果画面（正答率＋誤答の解説）
  if (pos >= order.length) {
    const total = order.length;
    let correct = 0;
    const wrongs = [];
    for (let p = 0; p < total; p++) {
      const wq = L(QUIZ_BANK[order[p]], lang);
      const ch = history[p];
      if (ch === wq.a) correct++; else wrongs.push({ wq, ch });
    }
    const frate = total ? Math.round((correct / total) * 100) : 0;
    return (
      <div>
        <div style={{ textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "クイズ完了" : "Quiz complete"}</div>
          <div style={{ fontSize: 34, fontWeight: 800, color: frate >= PASS ? C.ok : C.ng }}>{frate}%</div>
          <div style={{ fontSize: 12.5, color: "#5d6c83", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${total} 問` : `${correct} / ${total} correct`}</div>
        </div>
        <div style={{ marginBottom: 14 }}><Bar pct={frate} color={frate >= PASS ? C.ok : C.ng} /></div>
        <button onClick={() => { setPos(0); setHistory({}); setStats({ c: 0, a: 0 }); }}
          style={{ width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer", marginBottom: 16 }}>
          {lang === "ja" ? "もう一度挑戦する" : "Try again"}
        </button>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.ink, marginBottom: 8 }}>
          {lang === "ja" ? `誤答 ${wrongs.length} 問（解説付き）` : `Incorrect: ${wrongs.length} (with explanations)`}
        </div>
        {wrongs.length === 0 && <div style={{ fontSize: 12.5, color: C.ok, fontWeight: 600 }}>{lang === "ja" ? "全問正解です。" : "All correct!"}</div>}
        {wrongs.map(({ wq, ch }, k) => (
          <div key={k} style={{ background: C.light, borderRadius: 9, padding: 12, marginBottom: 8, fontSize: 12.5, lineHeight: 1.6 }}>
            <div style={{ fontWeight: 700, color: C.ink, marginBottom: 6 }}>{k + 1}. {wq.q}</div>
            <div style={{ color: C.ng }}>{lang === "ja" ? "あなたの回答: " : "Your answer: "}{ch != null && wq.o[ch] != null ? `${"ABCD"[ch]}. ${wq.o[ch]}` : "—"}</div>
            <div style={{ color: C.ok }}>{lang === "ja" ? "正解: " : "Correct: "}{"ABCD"[wq.a]}. {wq.o[wq.a]}</div>
            <div style={{ marginTop: 4, color: "#5a6a85" }}>{wq.e}</div>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <button onClick={() => slot.save({ filter, mode, order, pos, history, stats }, filter === "ALL" ? (lang === "en" ? "All" : "全分野") : filter)} style={{ padding: "6px 14px", borderRadius: 8, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{slot.meta ? (lang === "en" ? "💾 Saved" : "💾 保存済") : (lang === "en" ? "💾 Save" : "💾 セーブ")}</button>
        {slot.meta && (<>
          <button onClick={async () => { const d = await slot.read(); if (!d) return; resumeRef.current = { order: d.order, pos: d.pos, history: d.history, stats: d.stats }; setFilter(d.filter || "ALL"); setMode(d.mode || "fixed"); setOrder(d.order || []); setPos(d.pos || 0); setHistory(d.history || {}); setStats(d.stats || { c: 0, a: 0 }); }} style={{ padding: "6px 14px", borderRadius: 8, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary), fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{lang === "en" ? "▶ Resume" : "▶ 続きから"}</button>
          <span style={{ fontSize: 11, color: "#5a7288" }}>{saveStamp(slot.meta.t)}</span>
          <button onClick={() => slot.remove()} style={{ marginLeft: "auto", padding: "6px 10px", borderRadius: 8, border: "1px solid #cbd5e1", background: "#fff", color: "#7d93a8", fontSize: 11, cursor: "pointer" }}>{lang === "en" ? "Delete" : "削除"}</button>
        </>)}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontSize: 12.5, color: "#5a6a85", fontWeight: 600 }}>{t.totalQuestions(order.length)}</div>
        <div style={{ display: "inline-flex", background: "#EDE9E0", borderRadius: 999, padding: 3 }}>
          {[["fixed", t.fixed], ["random", t.random]].map(([k, lbl]) => (
            <button key={k} onClick={() => setMode(k)}
              style={{ border: "none", cursor: "pointer", borderRadius: 999, padding: "6px 16px", fontSize: 12.5, fontWeight: 700,
                background: mode === k ? "#fff" : "transparent", color: mode === k ? nvInk(C.deep, "#ffffff") : nvInk("#8a8275", C.mid),
                boxShadow: mode === k ? "0 1px 2px rgba(0,0,0,0.08)" : "none" }}>
              {lbl}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{ padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer",
              border: `1px solid ${filter === k ? C.primary : C.mid}`,
              background: filter === k ? C.primary : "#fff", color: filter === k ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600 }}><DoneCheck on={domDone.has(k)} onToggle={(e) => domDone.toggle(k, e)} /><span>{k === "ALL" ? t.allDomains : k}</span></button>
        ))}
      </div>
      {stats.a > 0 && (
        <div style={{ marginBottom: 10 }}>
          <div style={{ fontSize: 12, color: "#5a6a85", marginBottom: 3 }}>{t.sessionRate(rate, stats.c, stats.a)}</div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
        </div>
      )}
      <QuestionCard Q={Q} sel={sel} choose={choose} next={next} lastBtn={pos === order.length - 1 ? t.seeResult : t.nextQuestion} lang={lang} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 14 }}>
        <button onClick={prev} disabled={pos === 0}
          style={{ padding: "10px 30px", borderRadius: 8, fontSize: 13.5, fontWeight: 700, cursor: pos === 0 ? "default" : "pointer",
            border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`, background: "#fff", color: pos === 0 ? "#b9c4d6" : nvInk(C.primary, "#ffffff") }}>
          {t.prevQuestion}
        </button>
        <span style={{ fontSize: 12.5, color: "#5d6c83", fontWeight: 600 }}>{pos + 1} / {order.length}</span>
        <button onClick={() => setPos(p => Math.min(order.length - 1, p + 1))} style={{ padding: "10px 30px", borderRadius: 8, fontSize: 13.5, fontWeight: 700, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, cursor: "pointer" }}>{t.nextQuestion}</button>
      </div>
    </div>
  );
}

function Exam({ onAnswer, lang }) {
  const t = UI[lang];
  const [setNo, setSetNo] = useState(null);
  const [examMode, setExamMode] = useState("practice");
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [answers, setAnswers] = useState({});
  const [sel, setSel] = useState(null);
  const [orderMode, setOrderMode] = useState("fixed");
  const [sessionQs, setSessionQs] = useState([]);
  const rawQs = sessionQs;
  const qs = rawQs.map(q => L(q, lang));
  const exLabels = EXAM_LABELS[lang];

  const start = (n) => {
    const base = EXAM_SETS[n];
    setSessionQs(orderMode === "random" ? shuffle(base) : base);
    setSetNo(n); setPos(0); setAnswers({}); setSel(null); setPhase("run");
  };

  const choosePractice = (i) => {
    if (sel !== null) return;
    setSel(i);
    const Q = qs[pos];
    onAnswer(Q.d, i === Q.a, normReviewExam(rawQs[pos]), "exam");
    setAnswers(a => ({ ...a, [pos]: i }));
  };
  const nextPractice = () => { setSel(null); if (pos + 1 >= qs.length) setPhase("result"); else setPos(pos + 1); };
  const chooseReal = (i) => { setAnswers(a => ({ ...a, [pos]: i })); };
  const nextReal = () => { if (pos + 1 >= qs.length) finishReal(); else setPos(pos + 1); };
  const prevReal = () => setPos(p => Math.max(0, p - 1));
  const finishReal = () => {
    qs.forEach((Q, idx) => { if (answers[idx] !== undefined) onAnswer(Q.d, answers[idx] === Q.a, normReviewExam(rawQs[idx]), "exam"); });
    setPhase("result");
  };

  if (phase === "select") {
    return (
      <div>
        <Card title={t.selectMode}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}>
            <div style={{ display: "inline-flex", background: "#EDE9E0", borderRadius: 999, padding: 4 }}>
              {[["practice", t.practiceMode], ["real", t.realMode]].map(([k, lbl]) => (
                <button key={k} onClick={() => setExamMode(k)}
                  style={{ border: "none", cursor: "pointer", borderRadius: 999, padding: "8px 22px", fontSize: 13.5, fontWeight: 700,
                    background: examMode === k ? "#fff" : "transparent", color: examMode === k ? nvInk(C.deep, "#ffffff") : nvInk("#8a8275", C.mid),
                    boxShadow: examMode === k ? "0 1px 2px rgba(0,0,0,0.08)" : "none" }}>
                  {lbl}
                </button>
              ))}
            </div>
          </div>
          <div style={{ display: "flex", justifyContent: "center", marginTop: 10, marginBottom: 8 }}>
            <div style={{ display: "inline-flex", background: "#EDE9E0", borderRadius: 999, padding: 3 }}>
              {[["fixed", t.fixed], ["random", t.random]].map(([k, lbl]) => (
                <button key={k} onClick={() => setOrderMode(k)}
                  style={{ border: "none", cursor: "pointer", borderRadius: 999, padding: "6px 18px", fontSize: 12.5, fontWeight: 700,
                    background: orderMode === k ? "#fff" : "transparent", color: orderMode === k ? nvInk(C.deep, "#ffffff") : nvInk("#8a8275", C.mid),
                    boxShadow: orderMode === k ? "0 1px 2px rgba(0,0,0,0.08)" : "none" }}>
                  {lbl}
                </button>
              ))}
            </div>
          </div>
          <div style={{ fontSize: 12.5, color: "#5d6c83", textAlign: "center", lineHeight: 1.6 }}>{examMode === "practice" ? t.practiceDesc : t.realDesc}</div>
        </Card>
        <Card title={t.examTitle}>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#475569" }}>{t.examDesc}</div>
        </Card>
        {[1, 2, 3, 4, 5].map(n => (
          <button key={n} onClick={() => start(n)}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer",
              display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>
              <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{t.set} {n}</span>
              <span style={{ fontSize: 12, color: "#5a6a85", marginLeft: 8 }}>{exLabels[n]}</span>
              <span style={{ fontSize: 12, color: "#5d6c83", marginLeft: 8 }}>{EXAM_SETS[n].length}{t.questions}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary }}>{t.start}</span>
          </button>
        ))}
        <div style={{ fontSize: 11.5, color: "#5d6c83", textAlign: "center", marginTop: 6 }}>{t.totalSets}</div>
      </div>
    );
  }

  if (phase === "result") {
    const recs = qs.map((q, idx) => ({ q, sel: answers[idx], correct: answers[idx] === q.a }));
    const c = recs.filter(r => r.correct).length;
    const rate = Math.round((c / qs.length) * 100);
    const passed = rate >= PASS;
    const byDom = DOMAINS.map(d => {
      const sub = recs.filter(r => r.q.d === d.id);
      return { ...d, total: sub.length, correct: sub.filter(r => r.correct).length };
    }).filter(d => d.total > 0);
    const wrong = recs.filter(r => !r.correct);
    const modeLabel = examMode === "real" ? t.realModeLabel : t.practiceModeLabel;
    return (
      <div>
        <div style={{ background: passed ? "#E6F4EC" : "#FBEAE8", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#5a6a85" }}>{t.setResult(setNo, modeLabel)}</div>
          <div style={{ fontSize: 40, fontWeight: 800, color: nvInk(passed ? C.ok : C.ng, passed ? "#E4F6EC" : "#FBE9E7", 3) }}>{rate}%</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: nvInk(passed ? C.ok : C.ng, passed ? "#E4F6EC" : "#FBE9E7", 3) }}>{passed ? t.reachedPass : t.pointsToGo(PASS - rate)}</div>
          <div style={{ fontSize: 12, color: "#5a6a85", marginTop: 4 }}>{t.correctOf(c, qs.length)}</div>
        </div>
        <Card title={t.domainBreakdown}>
          {byDom.map(d => (
            <div key={d.id} style={{ marginBottom: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span><span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>{t.domainNames[d.id]}</span>
                <strong style={{ color: nvInk(d.correct / d.total >= PASS / 100 ? C.ok : C.ng, C.light) }}>{d.correct}/{d.total}</strong>
              </div>
              <Bar pct={Math.round(d.correct / d.total * 100)} color={d.correct / d.total >= PASS / 100 ? C.ok : C.ng} />
            </div>
          ))}
        </Card>
        <Card title={t.wrongQuestions(wrong.length)}>
          {wrong.length === 0 ? <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div> :
            wrong.map((a, idx) => (
              <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
                <div style={{ fontWeight: 600, marginBottom: 4 }}>
                  <span style={{ background: DOM_HUE[a.q.d], color: nvInk("#ffffff", DOM_HUE[a.q.d]), borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{a.q.d}</span>{a.q.q}
                </div>
                <div style={{ color: nvInk(C.ng, "#ffffff"), fontSize: 12.5 }}>{t.yourAnswer}{a.sel !== undefined ? `${"ABCD"[a.sel]} ${a.q.o[a.sel]}` : t.unanswered}</div>
                <div style={{ color: nvInk(C.ok, "#ffffff"), fontSize: 12.5 }}>{t.answer}{"ABCD"[a.q.a]} {a.q.o[a.q.a]}</div>
                <div style={{ color: "#5a6a85", fontSize: 12.5, marginTop: 2 }}>{a.q.e}</div>
              </div>
            ))}
        </Card>
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => start(setNo)} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retry}</button>
          <button onClick={() => setPhase("select")} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
        </div>
      </div>
    );
  }

  const Q = qs[pos];
  if (examMode === "real") {
    const chosen = answers[pos];
    const answeredCount = Object.keys(answers).length;
    return (
      <div>
        <div style={{ marginBottom: 8 }}>
          <button onClick={() => setPhase("select")} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{t.toSetSelectShort}</button>
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 12.5, color: "#5a6a85" }}>
          <span>{t.questionNo(setNo, t.realModeLabel, pos + 1, qs.length)}</span>
          <span>{t.answeredCount(answeredCount, qs.length)}</span>
        </div>
        <Bar pct={Math.round((pos / qs.length) * 100)} color={C.primary} />
        <div style={{ marginTop: 12, background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{Q.d} · {t.domainNames[Q.d]}</div>
          <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
          {Q.o.map((opt, i) => {
            const active = chosen === i;
            return (
              <button key={i} onClick={() => chooseReal(i)}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px",
                  borderRadius: 9, border: `1.5px solid ${active ? C.primary : C.mid}`,
                  background: active ? C.light : "#fff", color: active ? C.deep : nvInk(C.ink, "#ffffff"),
                  cursor: "pointer", fontSize: 13.5, lineHeight: 1.4, fontWeight: active ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{"ABCD"[i]}</span>{opt}
              </button>
            );
          })}
          <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
            <button onClick={prevReal} disabled={pos === 0}
              style={{ flex: 1, padding: 12, borderRadius: 9, fontSize: 13.5, fontWeight: 700, cursor: pos === 0 ? "default" : "pointer",
                border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`, background: "#fff", color: pos === 0 ? "#b9c4d6" : nvInk(C.primary, "#ffffff") }}>
              {t.prev}
            </button>
            <button onClick={nextReal}
              style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
              {pos + 1 >= qs.length ? t.grade : t.next}
            </button>
          </div>
          {pos + 1 >= qs.length && answeredCount < qs.length && (
            <div style={{ fontSize: 11.5, color: C.ng, textAlign: "center", marginTop: 8 }}>{t.unansweredWarn(qs.length - answeredCount)}</div>
          )}
        </div>
      </div>
    );
  }

  const correctSoFar = Object.entries(answers).filter(([idx, v]) => v === qs[idx].a).length;
  const answeredCount = Object.keys(answers).length;
  return (
    <div>
      <div style={{ marginBottom: 8 }}>
        <button onClick={() => setPhase("select")} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{t.toSetSelectShort}</button>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 12.5, color: "#5a6a85" }}>
        <span>{t.questionNo(setNo, t.practiceModeLabel, pos + 1, qs.length)}</span>
        <span>{t.correctCount(correctSoFar, answeredCount)}</span>
      </div>
      <Bar pct={Math.round((pos / qs.length) * 100)} color={C.primary} />
      <div style={{ marginTop: 12 }}>
        <QuestionCard Q={Q} sel={sel} choose={choosePractice} next={nextPractice} lastBtn={pos + 1 >= qs.length ? t.seeResult : t.nextQuestion} lang={lang} />
      </div>
    </div>
  );
}

const AICX_EXAM_CASES = [{"id":"aicx-1","title":{"ja":"ケース：メリディア損害保険における保険金請求査定エージェントの導入判断","en":"Case: Deploying a Claims Adjudication Agent at Meridia General Insurance"},"body":{"ja":["メリディア損害保険（従業員4,200名、国内中堅）は、自動車保険の保険金請求（クレーム）査定業務にAIエージェントを導入するPoCを終えたところである。現在の査定は、受付センターの一次確認（書類不備チェック）、査定担当者（アジャスター）の損害額算定、SV（スーパーバイザー）の承認という3工程で回っている。月間の新規請求は約18,000件で、うち約62%が軽微・定型（バンパー擦過、単独物損など）だが、繁忙期にはアジャスターの残業が常態化し、平均査定リードタイムは5.4営業日に達している。経営陣は「リードタイム短縮」と「アジャスター1人あたり処理件数の向上」を強く求めている。","推進を担うのはデジタル戦略室の高梨室長で、生成AIエージェントに、書類のOCR抽出、損害区分の推定、過去類似事案の参照、支払見込額のドラフト作成までを担わせる構想を持つ。一方、査定部門長の黒田は品質と説明責任を重視し、「機械が金額を確定させ、後で契約者から異議が出たら誰が責任を取るのか」と懸念している。コンプライアンス部門は、支払拒否・減額を伴う判断は必ず人間の最終確認を通す必要があると釘を刺している。監督官庁への説明可能性（なぜその金額になったか）も要件だ。","データ整備は不完全である。過去5年の査定履歴はあるが、損害写真のメタデータやアジャスターの判断根拠がフリーテキストで散在し、構造化されていない。修理工場の見積データは提携工場分（全体の約55%）しか電子化されていない。PoCでは、比較的データの揃った「軽微・定型」カテゴリに絞ってエージェントを走らせた。","PoCは6週間、対象は軽微・定型カテゴリの実データ2,000件で実施した。エージェントの支払見込額ドラフトと、ベテランアジャスターの最終確定額を突き合わせて評価した。あわせて、フリーテキスト根拠から損害区分を推定するタスク、契約者への一次回答文面の生成も評価対象とした。判定基準（合格ライン）は事前にコンプライアンスと査定部門の合意で設定してある。","経営会議では、次フェーズで対象を「中程度の損害（人身なし・複数箇所損傷）」まで一気に広げ、自動化率（エージェントのドラフトがアジャスター修正なしで承認された割合）をKPIに据える案が出ている。同時に、初期投資と運用費に見合うROIを12か月以内に示せなければ予算を継続しない、という条件も付いている。現場のアジャスターからは「結局ドラフトの検証に時間がかかり、かえって遅くなる工程がある」との声も上がっている。"],"en":["Meridia General Insurance (4,200 employees, a mid-sized domestic carrier) has just finished a PoC to introduce an AI agent into its auto-insurance claims adjudication workflow. Adjudication currently runs in three stages: intake-center first check (document-completeness), the adjuster's loss-amount calculation, and supervisor (SV) approval. Monthly new claims total about 18,000, of which roughly 62% are minor/routine (bumper scuffs, single-vehicle property damage), yet during peak seasons adjuster overtime is chronic and the average adjudication lead time reaches 5.4 business days. Management is strongly pushing for shorter lead time and higher claims processed per adjuster.","The initiative is led by Takanashi, head of the Digital Strategy Office, who envisions the generative AI agent handling OCR extraction, damage-category inference, retrieval of similar past cases, and drafting an estimated payout. Meanwhile, claims division head Kuroda prioritizes quality and accountability, worrying, 'If the machine finalizes the amount and the policyholder later disputes it, who is responsible?' Compliance has flagged that any decision involving denial or reduction of payment must pass a final human check. Explainability to the regulator (why the amount was set) is also a requirement.","Data readiness is incomplete. Five years of adjudication history exists, but damage-photo metadata and adjusters' reasoning are scattered as free text and unstructured. Repair-shop estimate data is digitized only for partner shops (about 55% of the total). For the PoC, the agent was run on the relatively well-populated minor/routine category.","The PoC ran for six weeks over 2,000 real claims in the minor/routine category. The agent's draft estimated payout was compared against the final amount confirmed by veteran adjusters. Also evaluated were a task inferring damage category from free-text reasoning, and generation of a first-response message to the policyholder. Pass thresholds (acceptance lines) were agreed in advance by Compliance and the claims division.","In the management meeting, a proposal has emerged to expand the next phase all at once to 'moderate damage (no bodily injury, multiple damage points)' and to adopt the automation rate (share of agent drafts approved without adjuster edits) as a KPI. At the same time, a condition is attached: unless a 12-month ROI justifying the initial and running costs can be shown, the budget will not continue. Adjusters on the floor note that 'in some steps, verifying the draft actually takes time and slows things down.'"]},"tables":[{"title":{"ja":"表1 現行査定工程と担当・所要","en":"Table 1 Current adjudication stages, owners, and effort"},"headers":{"ja":["工程","担当","主な作業","平均所要","備考"],"en":["Stage","Owner","Main task","Avg. effort","Notes"]},"rows":{"ja":[["一次確認","受付センター","書類不備・本人確認","0.5営業日","定型チェック中心"],["損害額算定","アジャスター","損害区分・見積照合・金額算定","3.8営業日","繁忙期に滞留"],["承認","SV","算定妥当性の確認・決裁","1.1営業日","減額時は説明必須"]],"en":[["First check","Intake center","Doc completeness / ID check","0.5 business day","Mostly routine checks"],["Loss calculation","Adjuster","Category / estimate matching / amount","3.8 business days","Backlogs at peak"],["Approval","SV","Validity check and sign-off","1.1 business days","Explanation required on reduction"]]}},{"title":{"ja":"表2 対象カテゴリ・月間件数・リスク区分・主な根拠データ","en":"Table 2 Target categories, monthly volume, risk tier, and main evidence data"},"headers":{"ja":["カテゴリ","月間件数","リスク区分","主な根拠データ","データ整備度"],"en":["Category","Monthly volume","Risk tier","Main evidence data","Data readiness"]},"rows":{"ja":[["軽微・定型","約11,160件","低","写真・提携工場見積","高（構造化進む）"],["中程度（人身なし）","約4,860件","中","写真・非提携見積・現地調査","中（半構造化）"],["人身・重大","約1,980件","高","医療記録・過失割合・訴訟履歴","低（フリーテキスト多）"]],"en":[["Minor/routine","approx. 11,160","Low","Photos / partner-shop estimates","High (structuring underway)"],["Moderate (no injury)","approx. 4,860","Medium","Photos / non-partner estimates / on-site survey","Medium (semi-structured)"],["Bodily injury/serious","approx. 1,980","High","Medical records / fault ratio / litigation history","Low (much free text)"]]}},{"title":{"ja":"表3 PoC評価結果（結果 vs 判定基準）","en":"Table 3 PoC evaluation results (result vs. acceptance threshold)"},"headers":{"ja":["評価タスク","指標","PoC結果","判定基準","判定"],"en":["Task","Metric","PoC result","Threshold","Verdict"]},"rows":{"ja":[["支払見込額ドラフト","確定額との誤差±5%内割合","78%","≥90%","未達"],["支払見込額ドラフト","過大見積（払い過ぎ）率","6.2%","≤3%","未達"],["損害区分の推定","正解率","94%","≥90%","達成"],["一次回答文面の生成","そのまま送付可の割合","88%","≥85%","達成"]],"en":[["Estimated payout draft","Within ±5% of final amount","78%","≥90%","Not met"],["Estimated payout draft","Over-estimate (overpay) rate","6.2%","≤3%","Not met"],["Damage-category inference","Accuracy","94%","≥90%","Met"],["First-response generation","Send-as-is rate","88%","≥85%","Met"]]}},{"title":{"ja":"表4 ROI試算の前提（12か月）","en":"Table 4 ROI estimate assumptions (12 months)"},"headers":{"ja":["項目","値","算定根拠"],"en":["Item","Value","Basis"]},"rows":{"ja":[["初期投資","4,800万円","開発・データ整備・統合"],["年間運用費","1,560万円","API・保守・監視・HITL人件"],["削減対象工数","アジャスター換算 9.0名分","定型工程のドラフト自動化"],["1名あたり年間人件費","780万円","社内標準単価"],["過大見積による想定損失","年 約2,900万円","過大率6.2%前提の払い過ぎ"]],"en":[["Initial investment","JPY 48.0M","Development / data prep / integration"],["Annual running cost","JPY 15.6M","API / maintenance / monitoring / HITL labor"],["Effort to be reduced","9.0 adjuster-FTE equivalent","Draft automation of routine steps"],["Annual cost per FTE","JPY 7.8M","Internal standard rate"],["Assumed loss from over-estimate","approx. JPY 29.0M/yr","Overpay under 6.2% over-estimate rate"]]}}],"questions":[{"n":1,"q":{"ja":"初期スコープ設計において、メリディアがPoC後の第一段で最も優先して確定すべき成果物はどれか。ケース本文・表の制約に最も整合するものを選べ。","en":"In initial scope design, which deliverable should Meridia prioritize confirming first after the PoC? Choose the one most consistent with the case and table constraints."},"options":[{"label":{"ja":"軽微・定型カテゴリに限定し、金額ドラフトは提示のみ・確定は人が行う運用と、説明可能性を残す根拠出力の仕様を先に固める","en":"Limit to minor/routine, define a workflow where the amount is only a draft with human finalization, and fix the evidence-output spec preserving explainability first"},"ok":true,"exp":{"ja":"金額誤差・過大率が基準未達（表3）で、コンプライアンスは減額判断に人の最終確認を要求。低リスクに絞りドラフト提示に留め、監督官庁向け説明性の仕様を先に固めるのが制約に最も整合する。","en":"Payout error/over-estimate miss thresholds (Table 3), and Compliance requires human finalization on reductions. Scoping to low risk, keeping amounts as drafts, and fixing the explainability spec best fits the constraints."}},{"label":{"ja":"中程度カテゴリまで含めた金額自動確定の範囲を定義し、非提携工場見積の電子化を同時並行で進めて対象件数を最大化する","en":"Define an auto-finalization scope including moderate cases and digitize non-partner estimates in parallel to maximize covered volume"},"ok":false,"exp":{"ja":"中程度はデータ整備が中・非提携見積が未電子化（表2）で、金額自動確定はコンプライアンス要件と表3の未達に反する。件数最大化を優先しリスク統制を後回しにしている。","en":"Moderate cases have medium readiness and non-digitized non-partner estimates (Table 2); auto-finalizing amounts violates Compliance and Table 3 misses. It prioritizes volume over risk control."}},{"label":{"ja":"自動化率KPIの目標値を先に経営と合意し、その達成に必要なモデル精度の改善計画とアジャスターの再配置案までを一体の成果物として確定してから運用設計に入る","en":"Agree the automation-rate KPI target with management first, then confirm as one integrated deliverable the model-accuracy improvement plan and the adjuster reassignment plan before starting operational design"},"ok":false,"exp":{"ja":"自動化率を先行KPI化すると、金額基準未達・説明責任という上位制約を飛ばして数値目標が独走する。順序として統制設計とスコープ確定が先で、KPIは従うべき。","en":"Leading with an automation-rate KPI lets a numeric target run ahead of the higher constraints of unmet amount thresholds and accountability. Control design and scope should come first; the KPI follows."}},{"label":{"ja":"過去5年のフリーテキスト査定根拠を全件構造化する基盤整備を最優先の成果物とし、完了後にエージェント運用の範囲を検討する","en":"Make full structuring of five years of free-text reasoning the top-priority deliverable, and consider the agent's operating scope only after it completes"},"ok":false,"exp":{"ja":"全件構造化は有用だが、軽微・定型は既にデータが揃い区分推定も基準達成（表2・3）。全整備完了を待つのは即効性のある低リスク運用の機会を逃し、経営のリードタイム要求にも反する。","en":"Full structuring helps, but minor/routine is already well-populated and category inference passes (Tables 2/3). Waiting for full prep misses the ready low-risk win and conflicts with management's lead-time demand."}}]},{"n":2,"q":{"ja":"HITL（人間関与）とエスカレーションの設計として、ケースの品質・コンプライアンス要件に最も適合するのはどれか。","en":"Which HITL and escalation design best fits the case's quality and compliance requirements?"},"options":[{"label":{"ja":"減額・支払拒否を含む案件と、確定額との誤差が閾値を超える恐れのある案件を人の確認に回し、それ以外の定型ドラフトはSV承認前に検証を軽量化する","en":"Route reduction/denial cases and those at risk of exceeding the amount-error threshold to human review, while lightening verification before SV approval for other routine drafts"},"ok":true,"exp":{"ja":"コンプライアンスは減額・拒否に人の最終確認を必須とし、金額誤差は基準未達。リスクの高い判断を選別してHITLに載せ、低リスク定型は軽量化する設計が要件に最も適合する。","en":"Compliance mandates human finalization on reductions/denials and amount error misses the threshold. Selecting high-risk decisions for HITL while lightening low-risk routine best fits the requirements."}},{"label":{"ja":"全案件をエージェントが自動確定し、契約者から異議が出た案件のみ事後にアジャスターが再査定するフィードバック方式に一本化する","en":"Have the agent auto-finalize all cases and unify on a feedback scheme where adjusters re-adjudicate only cases the policyholder disputes"},"ok":false,"exp":{"ja":"事後のみの人関与は、減額・拒否に事前の人確認を求めるコンプライアンス要件に真っ向から反する。異議前提の設計は説明責任と信頼を損なう。","en":"Post-hoc-only human involvement directly violates Compliance's requirement of prior human review on reductions/denials. A dispute-driven design harms accountability and trust."}},{"label":{"ja":"全案件を一律にアジャスターの二重確認とし、エージェント出力はあくまで参考情報として扱い、現行の3工程を維持したまま繁忙期は増員で処理量に対応する運用へ切り替える","en":"Apply uniform adjuster double-checking to all cases, treat agent output as reference only, keep the current three stages, and switch to handling peak volume by adding staff"},"ok":false,"exp":{"ja":"一律二重確認は安全側だが、リードタイム短縮と処理件数向上という経営要求・削減工数（表4）を放棄する。リスクに応じた強弱がなく、現場の遅延懸念を悪化させる。","en":"Uniform double-checking is safe but abandons management's lead-time/throughput goals and the effort savings (Table 4). Lacking risk-based modulation, it worsens the floor's delay concern."}},{"label":{"ja":"エスカレーション基準を損害区分の推定確信度のみで設定し、確信度が低い案件だけを人に回して金額の妥当性チェックは省略する","en":"Set escalation solely on damage-category inference confidence, routing only low-confidence cases to humans and omitting amount-validity checks"},"ok":false,"exp":{"ja":"区分推定は基準達成だが、問題は金額誤差・過大率（表3）。確信度のみを基準にし金額チェックを省くと、最も統制すべき過大見積リスクを見逃す。","en":"Category inference passes, but the problem is amount error/over-estimate (Table 3). Basing escalation on confidence alone and skipping amount checks misses the over-estimate risk that most needs control."}}]},{"n":3,"q":{"ja":"運用開始後、エージェントが特定期間に過大見積のドラフトを連続生成し、一部がSV承認を通過して過払いが発生した疑いがある。インシデント初動と影響区分として最も適切なのはどれか。","en":"After go-live, the agent generated over-estimate drafts consecutively during a period, some passed SV approval, and overpayment is suspected. Which incident first response and impact scoping is most appropriate?"},"options":[{"label":{"ja":"該当期間の当該経路のドラフト自動生成を停止し、過大率が基準を超えた案件を抽出して承認済み・支払済みの範囲を特定、影響区分を確定してから再開可否を判断する","en":"Halt auto-drafting on the affected path for the period, extract cases exceeding the over-estimate threshold, identify the approved/paid scope, fix the impact classification, then decide on resumption"},"ok":true,"exp":{"ja":"過払いは金銭・説明責任に直結。まず当該経路を止め、基準超過案件と支払済み範囲を特定して影響を区分する封じ込め優先が定石。再開はその後の判断とするのが適切。","en":"Overpayment directly affects money and accountability. Containment first—halt the affected path, identify threshold-exceeding and paid cases, and classify impact—is standard; resumption follows."}},{"label":{"ja":"システム全体を即時全面停止し、稼働中の全カテゴリの全案件を一律に手作業へ戻したうえで、根本原因の特定と再発防止策の実装が完了するまでは全面再開しない方針とする","en":"Immediately shut the entire system down, revert all cases in all active categories to manual, and announce company-wide a policy of no full restart until root cause is found and preventive measures are implemented"},"ok":false,"exp":{"ja":"全面停止は過剰反応。問題は特定経路の過大見積であり、影響のない経路まで止めるとリードタイム悪化と現場混乱を招く。封じ込めは影響範囲を絞って行うのが原則。","en":"A full shutdown over-reacts. The issue is over-estimates on a specific path; halting unaffected paths worsens lead time and disrupts the floor. Containment should be scoped to the affected area."}},{"label":{"ja":"過払いの疑いがある契約者にまず個別連絡して返還を依頼し、事実確認と原因調査は契約者対応が一巡した後にまとめて着手する","en":"First contact individually the policyholders suspected of overpayment to request refunds, and begin fact-finding and cause investigation only after that outreach concludes"},"ok":false,"exp":{"ja":"影響範囲・事実未確定のまま契約者に返還依頼するのは、説明責任・信頼を損ない誤連絡のリスクが高い。初動は封じ込めと影響特定が先で、対外対応はその後。","en":"Requesting refunds before scope and facts are established harms accountability and trust and risks erroneous contact. First response is containment and impact identification; external outreach follows."}},{"label":{"ja":"承認を通過した以上SV側の確認責任と整理し、エージェントは継続稼働のまま、過大率の監視閾値をやや厳しくして次回の再発を防ぐ運用に切り替える","en":"Treat it as the SV's review responsibility since it passed approval, keep the agent running, and merely tighten the over-estimate monitoring threshold to prevent recurrence next time"},"ok":false,"exp":{"ja":"責任の押し付けと閾値微調整だけでは、既発の過払いという現に生じた影響の特定・是正を放置することになる。初動で必要なのは封じ込めと影響区分であり、稼働継続は不適切。","en":"Shifting blame and only nudging the threshold leaves the already-incurred overpayment unidentified and uncorrected. First response requires containment and impact scoping; continued running is inappropriate."}}]},{"n":4,"q":{"ja":"次フェーズのKPIに「自動化率（アジャスター修正なし承認割合）」を単独主要指標として据える案について、最も妥当な評価はどれか。","en":"Regarding adopting the 'automation rate (share approved without adjuster edits)' as the sole primary KPI for the next phase, which assessment is most valid?"},"options":[{"label":{"ja":"自動化率を単独KPIにすると過大見積を見逃す誘因が生じるため、金額誤差・過大率など品質指標とセットで管理し、自動化率は補助指標に留めるべきである","en":"A sole automation-rate KPI creates an incentive to overlook over-estimates, so it should be managed together with quality metrics like amount error/over-estimate and kept as a secondary indicator"},"ok":true,"exp":{"ja":"自動化率のみを追うと修正回避圧力が働き、基準未達の過大率（表3）を悪化させかねない。品質指標と併用し補助指標化するのが、統制と経営要求の両立に最も妥当。","en":"Chasing automation rate alone pressures against edits and can worsen the already-failing over-estimate rate (Table 3). Pairing with quality metrics and keeping it secondary best balances control and business goals."}},{"label":{"ja":"自動化率はリードタイムと処理件数の向上に直結する最重要指標であり、目標値を高く設定したうえでアジャスターによる修正介入を抑制する運用を全カテゴリで徹底すべきである","en":"The automation rate is the most important metric tied directly to improving lead time and throughput, so a high target should be set and adjuster edit intervention thoroughly suppressed across all categories"},"ok":false,"exp":{"ja":"修正介入の抑制は、金額誤差・過大率という未達の品質問題を悪化させる。効率指標を単独最重要化する発想は、コンプライアンス要件と表3の実態を無視している。","en":"Suppressing edits worsens the failing amount-error/over-estimate quality issues. Elevating an efficiency metric alone ignores Compliance requirements and the reality in Table 3."}},{"label":{"ja":"自動化率は区分推定の正解率が基準を満たしている以上妥当なKPIであり、金額の品質は承認工程のSVが担保するため単独指標化して差し支えない","en":"Since category-inference accuracy passes, the automation rate is a valid KPI; amount quality is assured by the SV in approval, so making it the sole indicator is fine"},"ok":false,"exp":{"ja":"区分推定の達成と金額品質は別問題（表3で金額は未達）。SV承認は現に過大が通過し得るため単独指標の担保にならない。品質指標の併設が必要。","en":"Passing category inference differs from amount quality (amount fails in Table 3). SV approval can let over-estimates through, so it cannot back a sole indicator. Quality metrics must accompany it."}},{"label":{"ja":"自動化率は現場の納得を得にくいため主要指標から外し、代わりに契約者満足度と一次回答文面の送付可率を新たな単独KPIとして採用すべきである","en":"Because the automation rate is hard for the floor to accept, drop it from primary metrics and instead adopt policyholder satisfaction and first-response send-as-is rate as the new sole KPI"},"ok":false,"exp":{"ja":"満足度や文面送付可率は達成済みだが、核心の金額品質・過大率のリスクを測れない。別の単独指標に置き換えるだけでは、統制すべき損失リスクを依然見逃す。","en":"Satisfaction and send-as-is rate already pass but cannot measure the core amount-quality/over-estimate risk. Swapping in another sole indicator still misses the loss risk needing control."}}]},{"n":5,"q":{"ja":"ROI試算（表4）と次フェーズ拡大の判断について、経営の12か月条件を踏まえた最も妥当な解釈・提言はどれか。","en":"Regarding the ROI estimate (Table 4) and next-phase expansion, which interpretation/recommendation is most valid given management's 12-month condition?"},"options":[{"label":{"ja":"人件削減効果は投資回収に足り得るが、過大見積による想定損失が便益を大きく相殺するため、拡大前に過大率を基準内へ改善することを回収成立の前提条件に据える","en":"Labor savings may suffice for payback, but the assumed over-estimate loss largely offsets the benefit, so bringing the over-estimate rate within threshold before expansion should be a precondition for viability"},"ok":true,"exp":{"ja":"削減便益（9.0名×780万＝約7,020万）に対し運用費1,560万と過大損失2,900万が重く相殺する（表4）。過大率の是正を回収の前提に置く解釈が、数値と経営条件に最も整合する。","en":"Against savings (9.0 FTE x 7.8M = approx. 70.2M), running cost 15.6M and over-estimate loss 29.0M weigh heavily (Table 4). Making over-estimate correction a payback precondition best fits the numbers and the condition."}},{"label":{"ja":"削減工数9.0名分の人件費が初期投資を上回るため回収は明確であり、過大見積の想定損失は運用改善で自然に解消するとみなして予定どおり拡大を進める","en":"Since 9.0 FTE labor savings exceed the initial investment, payback is clear, and the over-estimate loss will resolve naturally through operational improvement, so proceed with expansion as planned"},"ok":false,"exp":{"ja":"過大損失2,900万・運用費1,560万を軽視しており、便益の相殺を過小評価。「自然に解消」の想定は基準未達（表3）の実態と噛み合わず、拡大判断として楽観的すぎる。","en":"It downplays the 29.0M over-estimate loss and 15.6M running cost, underestimating the offset. 'Resolves naturally' clashes with the failing thresholds (Table 3); too optimistic for an expansion call."}},{"label":{"ja":"12か月で回収を示せない懸念が強いため投資を打ち切り、エージェント構想自体を見送って現行の3工程体制の残業削減策に予算を振り替えるべきである","en":"Because payback within 12 months is doubtful, cancel the investment, shelve the agent initiative entirely, and redirect the budget to overtime-reduction measures in the current three-stage setup"},"ok":false,"exp":{"ja":"削減便益は運用費を上回り、過大率是正で回収可能性は残る。区分推定・文面生成は基準達成（表3）で価値がある。全面打ち切りは達成済みの便益まで捨てる過剰反応。","en":"Savings exceed running cost and payback remains feasible with over-estimate correction. Category inference and message generation already pass (Table 3) and add value. Full cancellation over-reacts by discarding proven benefits."}},{"label":{"ja":"回収を確実にするには対象を中程度カテゴリまで一気に広げて削減工数を積み増すのが最善であり、過大見積は件数の増加による平均化で相対的に希薄化していくと解釈して差し支えない","en":"To secure payback, expanding all at once to moderate cases to add savings is best, and it is fine to interpret that over-estimates dilute relatively through averaging as volume grows"},"ok":false,"exp":{"ja":"件数増で過大率が希薄化するという解釈は誤り。むしろデータ整備が劣る中程度への急拡大は過大損失を拡大しかねない（表2・3）。回収の前提を崩す危険な拡大論。","en":"The claim that volume dilutes the over-estimate rate is wrong; rushing into less-ready moderate cases can enlarge the over-estimate loss (Tables 2/3). A risky expansion that undermines payback."}}]}]},{"id":"aicx-2","title":{"ja":"AICX ケース試験（上級）：物流・製造のマルチエージェント・オーケストレーション","en":"AICX Case Exam (Advanced): Multi-Agent Orchestration in Logistics and Manufacturing"},"body":{"ja":["北陸精機ロジスティクス（以下HSL）は、精密部品の製造と第三者物流（3PL）を兼営する中堅企業である。同社は受注から在庫引当、配車、取引先照会までを複数の専門エージェントで自動化する基盤「MAGI-Flow」を本番投入し、運用3か月が経過した。月間受注はおよそ200,000件に達し、繁忙期にはピークが平時の2倍に振れる。","MAGI-Flowには立場の異なる関係者が関与する。倉庫現場は処理速度と欠品回避を重視し、IT基盤チームは可用性とコストを、リスク・コンプライアンス部門は監査証跡とPII保護を、経営はコスト上限と取引先SLAの遵守を求める。さらに主要取引先は納期連携のSLA未達に違約金条項を課しており、各者の要求はしばしば相反する。","アーキテクチャは、オーケストレーター（A5）がタスクを振り分け、需要予測（A1）・在庫配分（A2）・配送計画（A3）・取引先照会（A4）の専門エージェントが実務を担い、監査／ガードレール（A6）が横断的にログ検査とPII遮断を行う構成である（表1）。書込や外部送信を伴うエージェントには、権限分離と承認ゲートが設計上課されている。","ただしデータ整備は不完全で、ERPマスタの約12%に欠損があり、取引先マスタの表記揺れも残る。このため需要予測の確信度は品目により大きくばらつき、プロンプトに個人情報が紛れ込む経路も塞ぎきれていない。現場は自動化の恩恵を実感する一方、例外処理の増加に不安を抱いている。","直近3か月のKPI（表2）は一見良好だ。受注自動処理率は62%から78%へ上がり、在庫引当エラー率は3.8%から2.1%へ改善、人手介入率も18%から11%へ下がった。しかし平均オーケストレーション・レイテンシは8.2秒から12.1秒へ悪化し、SLA達成率は96%から91%へ低下、エージェント経由コストは4,200円から5,300円（千件あたり）へ上昇している。","6月にはインシデントが相次いだ（表3）。A4がテンプレート外の価格情報を取引先へ送信（INC-01）、A3の経路探索APIタイムアウトによる配送遅延（INC-02）、承認前のWMS在庫引当の書込（INC-03）、予測ログへのPII混入（INC-04）、そしてA1停止時の無制限リトライによる連鎖遅延（INC-05）が記録された。","コスト内訳（表4）を見ると、6月の主要項目合計は約209万円で、ツール／外部APIのうち経路探索API（A3）が38万円と突出し、A2の人手承認が32万円で続く。経営はコスト上限を千件あたり5,000円と定めており、6月実績はこれを超過している。","SLA・判定基準（表5）に照らすと、6月は応答SLA・レイテンシ上限・コスト上限・監査要件の4項目が未達で、在庫引当精度と自動処理率のみ達成した。取引先条項では応答SLA未達の月ごとに違約金¥1,500,000が発生する。経営は次四半期に向け、限られた投資で複数の制約を同時に満たす改善順序を求めている。"],"en":["Hokuriku Seiki Logistics (HSL) is a mid-sized company that both manufactures precision parts and runs third-party logistics (3PL). It has put into production a platform, 'MAGI-Flow,' that automates the flow from order intake through inventory allocation, dispatch planning, and supplier inquiry using several specialist agents, and three months of operation have now passed. Monthly orders reach roughly 200,000, with peaks swinging to twice the normal level in busy seasons.","MAGI-Flow involves stakeholders with differing stances. The warehouse floor prioritizes processing speed and avoiding stockouts; the IT platform team weighs availability and cost; the risk and compliance function demands audit trails and PII protection; and management insists on the cost ceiling and adherence to partner SLAs. Moreover, key partners impose penalty clauses for SLA breaches on delivery coordination, so the parties' demands frequently conflict.","In the architecture, the orchestrator (A5) routes tasks, the specialist agents for demand forecasting (A1), inventory allocation (A2), dispatch planning (A3), and supplier inquiry (A4) do the operational work, and the audit/guardrail agent (A6) performs cross-cutting log inspection and PII blocking (Table 1). Agents that write or send externally are, by design, subject to permission separation and approval gates.","However, data readiness is incomplete: about 12% of the ERP master data is missing, and inconsistencies in partner master records remain. As a result, forecast confidence varies widely by item, and the paths by which personal information slips into prompts are not fully closed. While the floor feels the benefits of automation, it is uneasy about the rise in exception handling.","The KPIs of the past three months (Table 2) look good at first glance. The order auto-processing rate rose from 62% to 78%, the allocation error rate improved from 3.8% to 2.1%, and the human-intervention rate fell from 18% to 11%. Yet average orchestration latency worsened from 8.2 to 12.1 seconds, the SLA attainment rate fell from 96% to 91%, and agent-mediated cost rose from ¥4,200 to ¥5,300 per thousand orders.","In June, incidents came in quick succession (Table 3): A4 sent out-of-template pricing information to a partner (INC-01); a route-search API timeout in A3 caused a delivery delay (INC-02); a WMS inventory allocation was written before approval (INC-03); PII was mixed into forecast logs (INC-04); and unbounded retries when A1 went down caused cascading delay (INC-05).","Looking at the cost breakdown (Table 4), the total of major items for June was about ¥2.09 million; among tools/external APIs, the route-search API (A3) stands out at ¥380,000, followed by A2's human approval at ¥320,000. Management has set the cost ceiling at ¥5,000 per thousand orders, and June's actual exceeded it.","Against the SLA/decision criteria (Table 5), June failed four items—response SLA, latency ceiling, cost ceiling, and audit requirement—while meeting only allocation accuracy and the auto-processing rate. Under the partner clause, a penalty of ¥1,500,000 is incurred for each month the response SLA is missed. For the next quarter, management wants an improvement sequence that satisfies multiple constraints at once with limited investment."]},"tables":[{"title":{"ja":"表1: エージェント構成・権限・ツール","en":"Table 1: Agent Configuration, Permissions, and Tools"},"headers":{"ja":["ID","エージェント","主な役割","書込権限","利用ツール","承認要否"],"en":["ID","Agent","Main role","Write permission","Tools used","Approval"]},"rows":{"ja":[["A1","需要予測","需要予測の算出","なし（読取のみ）","ERP読取／予測API","不要"],["A2","在庫配分","WMS在庫引当の更新","WMS書込","引当最適化API","必須（人手承認）"],["A3","配送計画","配車ルート生成","TMS書込（計画枠）","経路探索API","事後確認"],["A4","取引先照会","取引先への照会送信","外部送信","メール／取引先API","必須（テンプレ限定）"],["A5","オーケストレーター","タスク振分と統合","なし","内部呼出のみ","不要"],["A6","監査／ガードレール","ログ検査・PII遮断","監査ログのみ","PII検出／ポリシAPI","常時"]],"en":[["A1","Demand forecast","Compute demand forecast","None (read-only)","ERP read / forecast API","Not required"],["A2","Inventory allocation","Update WMS allocation","WMS write","Allocation-optimization API","Required (human approval)"],["A3","Dispatch planning","Generate delivery routes","TMS write (plan slot)","Route-search API","Post-hoc review"],["A4","Supplier inquiry","Send inquiries to partners","External send","Email / partner API","Required (template-limited)"],["A5","Orchestrator","Route and integrate tasks","None","Internal calls only","Not required"],["A6","Audit / guardrail","Log inspection, PII blocking","Audit log only","PII-detect / policy API","Always"]]}},{"title":{"ja":"表2: 月次KPI（4〜6月）","en":"Table 2: Monthly KPIs (Apr–Jun)"},"headers":{"ja":["指標","4月","5月","6月","目標／上限"],"en":["Metric","Apr","May","Jun","Target / ceiling"]},"rows":{"ja":[["受注自動処理率","62%","71%","78%","≥75%"],["在庫引当エラー率","3.8%","2.9%","2.1%","≤2.5%"],["平均オーケストレーション・レイテンシ（秒）","8.2","9.5","12.1","≤10"],["エージェント経由コスト（円／千件）","4,200","4,600","5,300","≤5,000"],["人手介入率","18%","14%","11%","≤12%"],["SLA達成率（15分以内）","96%","94%","91%","≥95%"]],"en":[["Order auto-processing rate","62%","71%","78%","≥75%"],["Inventory-allocation error rate","3.8%","2.9%","2.1%","≤2.5%"],["Avg. orchestration latency (sec)","8.2","9.5","12.1","≤10"],["Agent-mediated cost (¥/1,000 orders)","4,200","4,600","5,300","≤5,000"],["Human-intervention rate","18%","14%","11%","≤12%"],["SLA attainment (within 15 min)","96%","94%","91%","≥95%"]]}},{"title":{"ja":"表3: インシデント記録（6月）","en":"Table 3: Incident Log (June)"},"headers":{"ja":["番号","事象","関与エージェント","影響","一次原因"],"en":["No.","Event","Agents involved","Impact","Primary cause"]},"rows":{"ja":[["INC-01","未承認の価格情報を取引先へ送信","A4","取引先信頼低下・是正謝罪","テンプレ外送信を許容する設定不備"],["INC-02","経路探索APIタイムアウトで配送遅延","A3","SLA違反1件","外部API遅延＋リトライ設計不足"],["INC-03","承認前にWMS在庫引当を書込","A2／A5","引当二重化・手戻り","オーケストレーターの承認フロー分岐バグ"],["INC-04","予測プロンプト・ログにPII混入","A1／A6","監査指摘・要報告","マスタからのPII除去漏れ"],["INC-05","A1停止時の連鎖リトライで遅延急増","A1／A5","全体レイテンシ悪化","無制限リトライとフォールバック不在"]],"en":[["INC-01","Sent unapproved pricing to a partner","A4","Partner trust loss; corrective apology","Config flaw allowing out-of-template sends"],["INC-02","Delivery delay from route-API timeout","A3","One SLA breach","External-API latency + weak retry design"],["INC-03","Wrote WMS allocation before approval","A2 / A5","Double allocation; rework","Orchestrator approval-flow branch bug"],["INC-04","PII mixed into forecast prompt logs","A1 / A6","Audit finding; reportable","Missed PII removal from master data"],["INC-05","Cascading retries on A1 outage spiked delay","A1 / A5","Overall latency worsened","Unbounded retries and no fallback"]]}},{"title":{"ja":"表4: 6月コスト内訳（主要項目, 円／月）","en":"Table 4: June Cost Breakdown (major items, ¥/month)"},"headers":{"ja":["エージェント","LLM推論","ツール／外部API","人手承認","小計"],"en":["Agent","LLM inference","Tools / external API","Human approval","Subtotal"]},"rows":{"ja":[["A1 需要予測","180,000","90,000","0","270,000"],["A2 在庫配分","240,000","60,000","320,000","620,000"],["A3 配送計画","210,000","380,000","0","590,000"],["A4 取引先照会","150,000","40,000","0","190,000"],["A5 オーケストレーター","300,000","0","0","300,000"],["A6 監査","120,000","0","0","120,000"],["合計","1,200,000","570,000","320,000","2,090,000"]],"en":[["A1 Demand forecast","180,000","90,000","0","270,000"],["A2 Inventory allocation","240,000","60,000","320,000","620,000"],["A3 Dispatch planning","210,000","380,000","0","590,000"],["A4 Supplier inquiry","150,000","40,000","0","190,000"],["A5 Orchestrator","300,000","0","0","300,000"],["A6 Audit","120,000","0","0","120,000"],["Total","1,200,000","570,000","320,000","2,090,000"]]}},{"title":{"ja":"表5: SLA・判定基準と取引先条項","en":"Table 5: SLA / Decision Criteria and Partner Clause"},"headers":{"ja":["項目","基準","6月実績","判定","備考"],"en":["Item","Criterion","June actual","Result","Notes"]},"rows":{"ja":[["応答SLA（15分以内）","≥95%","91%","未達","未達月ごとに違約金¥1,500,000"],["レイテンシ上限","≤10秒","12.1秒","未達","連鎖リトライが主因"],["コスト上限","≤5,000円／千件","5,300円／千件","未達","経路探索APIが押上げ"],["在庫引当精度","エラー≤2.5%","2.1%","達成","改善傾向"],["監査要件","全書込に承認記録","INC-03で欠落","未達","承認ゲート回避を検知"],["自動処理率","≥75%","78%","達成","目標超過"]],"en":[["Response SLA (within 15 min)","≥95%","91%","Fail","Penalty ¥1,500,000 per missed month"],["Latency ceiling","≤10 sec","12.1 sec","Fail","Cascading retries the main cause"],["Cost ceiling","≤¥5,000/1,000 orders","¥5,300/1,000 orders","Fail","Route-search API drives it up"],["Allocation accuracy","Error ≤2.5%","2.1%","Pass","Improving trend"],["Audit requirement","Approval record for all writes","Missing in INC-03","Fail","Approval-gate bypass detected"],["Auto-processing rate","≥75%","78%","Pass","Exceeds target"]]}}],"questions":[{"n":1,"q":{"ja":"表2のKPI推移に照らし、SLA達成率が96%から91%へ低下した最も妥当な主因はどれか。","en":"In light of the KPI trend in Table 2, which is the most plausible main cause of the SLA attainment rate falling from 96% to 91%?"},"options":[{"label":{"ja":"レイテンシが8.2秒から12.1秒へ悪化して15分SLAを圧迫し、INC-05の無制限リトライによる連鎖遅延が主因となった。","en":"Latency worsened from 8.2 to 12.1 seconds, squeezing the 15-minute SLA, and INC-05's unbounded retries drove cascading delay as the main cause."},"ok":true,"exp":{"ja":"表2でレイテンシは上限10秒を超えて悪化し、SLA達成率は96→91%へ低下。表3のINC-05（連鎖リトライ）とも整合し、因果が一貫する。","en":"In Table 2, latency worsened past the 10s ceiling as SLA attainment fell 96→91%. This aligns with INC-05 (cascading retries) in Table 3, giving a consistent causal chain."}},{"label":{"ja":"自動処理率が78%へ上がり人手介入率が11%へ下がった結果、最終確認の工程が薄くなり品質劣化がSLA違反として複数月にわたり顕在化した。","en":"As the auto-processing rate rose to 78% and human intervention fell to 11%, the final-check step thinned out and quality degradation surfaced as SLA breaches."},"ok":false,"exp":{"ja":"自動化進展と介入低下は表2の通りだが、SLA低下はレイテンシ悪化で説明でき、品質指標である引当エラー率はむしろ改善している。","en":"Automation gains and lower intervention are real, but the SLA drop is explained by latency; the quality indicator (allocation error rate) actually improved."}},{"label":{"ja":"在庫引当エラー率が期間を通じて上昇し処理の停滞と手戻りを生んだことが、SLA達成率を直接押し下げた主因である。","en":"A steady rise in the inventory-allocation error rate over the period caused stalls and rework, directly pushing down the SLA attainment rate."},"ok":false,"exp":{"ja":"表2の在庫引当エラー率は3.8→2.1%へ改善しており上昇していない。前提が事実に反するため誤り。","en":"Table 2 shows the allocation error rate improved from 3.8 to 2.1%, not rising; the premise contradicts the data."}},{"label":{"ja":"エージェント経由コストが5,000円上限を超えた結果、処理量が意図的に絞られSLAが低下したと解釈できる。","en":"Because agent-mediated cost exceeded the ¥5,000 ceiling, throughput was deliberately restrained and the SLA consequently declined."},"ok":false,"exp":{"ja":"コスト上限超過は事実だが、処理量を絞る仕組みは記載がなく、コストとSLAは相関にすぎない。因果を取り違えている。","en":"The cost overrun is real, but no throttling mechanism is described; cost and SLA are merely correlated, not causal."}}]},{"n":2,"q":{"ja":"INC-01・INC-03・INC-04と表5の監査未達を踏まえ、監査・ガバナンス上まず着手すべき是正はどれか。","en":"Given INC-01, INC-03, INC-04 and the audit shortfall in Table 5, which corrective action should be tackled first for audit and governance?"},"options":[{"label":{"ja":"書込・外部送信を行うA2／A4に承認ゲートと権限分離を強制し、A5の承認フロー分岐バグを直して全書込に承認記録を残す。","en":"Enforce approval gates and permission separation on the writing/sending agents A2/A4, fix A5's approval-branch bug, and keep an approval record for every write."},"ok":true,"exp":{"ja":"表5の監査要件はINC-03の承認欠落で未達。書込・送信を担うA2／A4に承認ゲートを効かせ分岐バグを直すのが根本策で、表1の権限設計とも整合する。","en":"Table 5's audit requirement fails due to INC-03's missing approval. Enforcing gates on A2/A4 and fixing the branch bug is the root fix, consistent with Table 1's permission design."}},{"label":{"ja":"A6ガードレールの検査範囲を広げてLLMによる出力監視を全エージェントに常時適用し、未承認送信やPII混入を出力段で検知・遮断する。","en":"Broaden A6's guardrail inspection to apply LLM-based output monitoring continuously across all agents, comprehensively detecting and blocking unapproved sends and PII at the output stage."},"ok":false,"exp":{"ja":"出力監視の拡張は補完策だが、表1のA6は監査ログのみで書込権限を持たず、承認ゲート欠落（INC-03）という根本原因を塞げない。","en":"Expanding output monitoring is only complementary; per Table 1, A6 has only audit logs and no write authority, so it cannot close the root cause—the missing approval gate (INC-03)."}},{"label":{"ja":"A4のテンプレを撤廃し全照会を人手送信へ戻すことで、取引先への価格情報の事故（INC-01）を確実に防ぐ。","en":"Abolish A4's templates and revert all inquiries to manual sending to reliably prevent partner incidents (INC-01)."},"ok":false,"exp":{"ja":"全照会の人手回帰は事故を減らしても表2の自動処理率を毀損し、A2の書込問題(INC-03)には無関係で過剰反応である。","en":"Reverting all inquiries to manual reduces incidents but harms Table 2's auto-processing rate, is unrelated to A2's write issue (INC-03), and over-corrects."}},{"label":{"ja":"PII混入（INC-04）の解消を最優先にマスタ整備の是正を先行し、承認フローの修正は次段階へ回す。","en":"Prioritize the PII contamination (INC-04) by fixing master data first, deferring the approval-flow work to a later phase."},"ok":false,"exp":{"ja":"PII対応も重要だが、表5で未達判定を生むのは承認記録の欠落であり、監査上の優先度はそちらが高い。順序が逆である。","en":"PII matters, but what triggers the fail in Table 5 is the missing approval record, which has higher audit priority; the ordering is reversed."}}]},{"n":3,"q":{"ja":"6月にコスト上限（5,000円／千件）を超過した。SLA・引当精度・監査要件を崩さずにコストを下げる最良の一手はどれか。","en":"June exceeded the cost ceiling (¥5,000/thousand orders). Which is the best single move to reduce cost without breaking SLA, allocation accuracy, or audit requirements?"},"options":[{"label":{"ja":"経路探索API（38万円で最大）の呼出をバッチ化・キャッシュ活用で減らし、A3の再探索頻度を抑える。","en":"Cut route-search API calls (the largest tool cost at ¥380k) via batching and caching, curbing A3's re-search frequency while preserving SLA and accuracy."},"ok":true,"exp":{"ja":"表4で最大のツール費は経路探索API38万円。呼出削減はSLAと引当精度を保ちつつ、表5のコスト上限超過を最も効率よく是正できる。","en":"In Table 4 the top tool cost is the ¥380k route-search API. Cutting calls preserves SLA and accuracy while most efficiently fixing Table 5's cost overrun."}},{"label":{"ja":"A2の人手承認（32万円）を自動承認へ切替え、承認記録を事後サンプリングに変更して承認コストと待ち時間を同時に圧縮する。","en":"Switch A2's human approval (¥320k) to auto-approval and move part of the approval records to after-the-fact sampling, compressing both approval cost and waiting time at once."},"ok":false,"exp":{"ja":"人手承認の自動化は32万円を削るが、表5の『全書込に承認記録』要件に反し、監査未達を固定化するため制約違反となる。","en":"Automating approval cuts ¥320k but violates Table 5's 'approval record for all writes,' locking in the audit failure—a constraint breach."}},{"label":{"ja":"需要予測A1の予測モデルを小型化してLLM推論費を段階的に下げ、月間の推論コスト全体を圧縮する。","en":"Shrink the A1 forecasting model to lower LLM inference cost and compress monthly inference spend."},"ok":false,"exp":{"ja":"A1のLLM費は18万円で最大ではなく、小型化は表2の引当精度を損なうおそれがあり、効果と副作用が見合わない。","en":"A1's LLM cost is ¥180k, not the largest, and shrinking it risks Table 2's allocation accuracy; benefit and side effect do not balance."}},{"label":{"ja":"オーケストレーターA5の推論を止めて振分を固定ルール化し、A5のLLM費を丸ごと削減する。","en":"Stop A5's inference and replace routing with fixed rules, eliminating A5's LLM cost entirely."},"ok":false,"exp":{"ja":"A5推論の固定ルール化は30万円を削るが例外処理を硬直させ、繁忙期のピーク変動への適応を失うため妥当でない。","en":"Fixing A5's routing cuts ¥300k but rigidifies exception handling and loses adaptability to peak swings in busy seasons—not appropriate."}}]},{"n":4,"q":{"ja":"レイテンシ是正のための基盤投資（初期300万円＋運用20万円／月）を検討する。取引先違約金150万円／月を前提とした回収可否の判断として最も適切なのはどれか。","en":"An infrastructure investment to fix latency (¥3M upfront + ¥0.2M/month running) is under review. Given the ¥1.5M/month partner penalty, which is the most appropriate payback judgment?"},"options":[{"label":{"ja":"純便益は月130万円（違約金150万−運用増20万）で、初期300万は約2.3か月で回収でき、監査も崩さず妥当。","en":"Net benefit is about ¥1.3M/month (¥1.5M penalty minus ¥0.2M added running cost); the ¥3M upfront pays back in about 2.3 months while keeping approval and accuracy constraints intact."},"ok":true,"exp":{"ja":"表5の違約金150万から運用増20万を引いた純便益130万で、300万÷130万≒2.3か月。監査・精度を崩さず投資判断として妥当。","en":"From Table 5's ¥1.5M penalty minus ¥0.2M running gives ¥1.3M net; ¥3M ÷ ¥1.3M ≈ 2.3 months. It holds audit and accuracy intact—a sound decision."}},{"label":{"ja":"違約金150万のみを便益とみなし、初期300万は約2か月で回収できるため直ちに実施すべきである。","en":"Treating only the ¥1.5M penalty as the benefit, the ¥3M upfront pays back in about 2 months, so implement immediately."},"ok":false,"exp":{"ja":"運用増20万を無視した300万÷150万＝2か月は過小評価。純便益ベースの約2.3か月が正しい。","en":"Ignoring the ¥0.2M running cost, ¥3M ÷ ¥1.5M = 2 months underestimates; the net-benefit figure of ~2.3 months is correct."}},{"label":{"ja":"回収に約半年かかりコスト上限も超えると誤認して投資を見送り、代わりにA2の人手承認を大幅に削減してコストを下げる。","en":"Payback takes about half a year and would exceed the cost ceiling, so shelve it and cut A2's human approval instead."},"ok":false,"exp":{"ja":"半年や上限超過は誤算であり、代替の人手承認削減は表5の監査要件に反するため二重に不適切。","en":"The half-year and ceiling claims miscalculate, and cutting human approval violates Table 5's audit requirement—doubly wrong."}},{"label":{"ja":"便益はレイテンシ改善のみで金額化できないため、投資判断は次四半期のKPIを待つべきである。","en":"The benefit is only latency improvement and cannot be monetized, so wait for next quarter's KPIs before deciding."},"ok":false,"exp":{"ja":"表5の違約金150万という金額化可能な便益を無視しており、投資保留の根拠として弱い。","en":"It ignores the monetizable ¥1.5M penalty in Table 5, making it a weak basis for deferring the investment."}}]},{"n":5,"q":{"ja":"INC-02（外部APIタイムアウト）とINC-05（連鎖リトライ）を踏まえ、部分障害時のフォールバック設計として最も適切なのはどれか。","en":"Given INC-02 (external API timeout) and INC-05 (cascading retries), which is the most appropriate fallback design for partial failures?"},"options":[{"label":{"ja":"サーキットブレーカと上限付きリトライを導入し、外部API障害時はキャッシュ済み経路へ縮退しつつ要確認フラグを付す。","en":"Introduce a circuit breaker and bounded retries, degrading gracefully to a cached route with a needs-review flag when the external API fails."},"ok":true,"exp":{"ja":"INC-02／05はAPI障害と無制限リトライが原因。ブレーカ＋上限リトライ＋縮退（キャッシュ経路＋要確認）が定石で、レイテンシとSLAを守る。","en":"INC-02/05 stem from API failure and unbounded retries. A breaker + bounded retries + degradation (cached route + review flag) is the standard, protecting latency and SLA."}},{"label":{"ja":"障害検知時はオーケストレーターが全エージェントを一旦停止し、復旧確認後に全処理を再実行することで整合性を最優先に担保する。","en":"On fault detection, have the orchestrator halt all agents and, after recovery, re-run all processing so that consistency is guaranteed above everything else."},"ok":false,"exp":{"ja":"全停止・全再実行は整合性を守るが、表5のレイテンシ上限10秒とSLAを大きく損ない、繁忙期には被害を拡大する。","en":"A full halt and re-run preserves consistency but severely harms Table 5's 10s latency ceiling and the SLA, amplifying damage during peaks."}},{"label":{"ja":"リトライ回数を増やしタイムアウトを延長することで、外部API呼出の最終的な成功率を高める。","en":"Increase retry counts and extend timeouts to raise the eventual success rate of external-API calls."},"ok":false,"exp":{"ja":"リトライ増・タイムアウト延長はINC-05の教訓に逆行し、レイテンシをさらに悪化させるため不適切。","en":"More retries and longer timeouts run counter to INC-05's lesson and worsen latency further—inappropriate."}},{"label":{"ja":"A3を常時キャッシュ経路のみで運用し、外部の経路探索APIを完全に廃止して障害要因を根絶する。","en":"Run A3 solely on cached routes at all times and retire the external route-search API to eliminate the fault source."},"ok":false,"exp":{"ja":"キャッシュ経路のみの常用は経路品質を落とし配送効率を毀損するため、過剰な縮退で妥当でない。","en":"Running only on cached routes degrades route quality and delivery efficiency—an excessive degradation, not appropriate."}}]},{"n":6,"q":{"ja":"コスト・レイテンシ・SLAの全制約が未達で関係者の要求が相反するなか、次四半期に最優先すべき改善はどれか。","en":"With cost, latency, and SLA all failing and stakeholder demands in conflict, which improvement should be top priority next quarter?"},"options":[{"label":{"ja":"レイテンシを最優先で是正する。リトライ抑制と縮退設計はSLA違約金とAPIコストを同時に下げ、複数制約に波及するため。","en":"Fix latency first: curbing retries and adding graceful degradation lowers both the SLA penalty and API cost, so it propagates across multiple constraints."},"ok":true,"exp":{"ja":"レイテンシ是正は表5のSLA未達とINC-05由来のリトライコストを同時に下げ、複数の未達に効く最短経路となる。","en":"Fixing latency simultaneously lowers Table 5's SLA failure and INC-05's retry cost, the shortest path that touches multiple failures."}},{"label":{"ja":"違約金回避を最優先にSLAを短期で戻すべく、当面は人手介入率を引き上げて確認工程を厚くし、レイテンシ対策は次段階に回す。","en":"To avoid the partner penalty first, thicken the checking step by raising the human-intervention rate to restore the SLA in the short term, deferring latency work to a later phase."},"ok":false,"exp":{"ja":"人手介入を厚くすると表4の人手承認コストと表2の介入率が上がり、根本原因のレイテンシを放置するため逆効果。","en":"Thickening human intervention raises Table 4's approval cost and Table 2's intervention rate while leaving the root latency cause—counterproductive."}},{"label":{"ja":"コスト上限超過が経営リスクのため、まず経路探索APIとA5推論を削減してコストから着手する。","en":"Because the cost-ceiling overrun is a management risk, first cut the route-search API and A5 inference to start from cost."},"ok":false,"exp":{"ja":"コスト先行はA5削減でSLAや適応性を損ないかねず、レイテンシの根本が残るため単発効果にとどまる。","en":"Leading with cost may harm SLA and adaptability via A5 cuts, and the latency root remains—only a one-off effect."}},{"label":{"ja":"監査未達が最も重大なため全書込への承認ゲート整備を最優先し、他の制約は次四半期へ順送りにする。","en":"Because the audit shortfall is most serious, prioritize building approval gates and defer the other constraints to next quarter."},"ok":false,"exp":{"ja":"監査整備は重要だが単一制約にとどまり、表5で2項目の未達を生むレイテンシほど広く効かない。","en":"Audit work matters but addresses a single constraint; it lacks latency's breadth, which drives two failures in Table 5."}}]}]},{"id":"aicx-3","title":{"ja":"ケース: ソルフィア損害保険「LexGround」— RAG根拠の版管理・幻覚インシデントと説明責任","en":"Case: Solphia P&C Insurance 'LexGround' — RAG Grounding Version Control, Hallucination Incidents, and Accountability"},"body":{"ja":["ソルフィア損害保険は、給付査定と約款照会を支援するRAG（検索拡張生成）アシスタント「LexGround」を査定部門400名に展開している。LexGroundは約款DB・社内FAQ・外部判例集・監督指針・過去回答ログを根拠として引用し、査定担当が顧客への回答文面を作成する際の下書きと根拠リンクを提示する。経営は「1件あたり処理時間の短縮」と「根拠提示による説明品質の均質化」を導入目的に掲げ、当年度のROI達成を強く求めている。","6月、二件の重大事案が続いた。ひとつは存在しない判例を根拠として提示し免責を示唆した回答（I-105）で、コンプライアンス部門は監督当局への報告が必要と判断した。もうひとつは、改定前の旧約款の免責条項を最新であるかのように引用した回答（I-102）で、顧客通知が必要になった。法務部門は「誤りそのものより、なぜその根拠が提示されたのかを事後に再現・説明できないことが問題だ」と強く指摘した。","関係者の要望は相反する。経営はグラウンディング率の改善を評価し、モデル更新版v1.3の全社即時展開とROI回収を優先したい。法務・コンプラは根拠の版整合と監査可能性（誰にどの版を根拠として提示したかの再現）を最優先に据える。現場の査定担当は応答レイテンシの悪化と下書きの手戻りを嫌う。データ整備チームは、根拠源の版管理不備こそが根本原因だと訴えるが、整備にはリソースと時間が要る。","根拠データ源の整備度には大きなばらつきがある。約款DBは版番号と日付で管理され監査ログも残るが、社内FAQは上書き更新で版が残らず監査ログもない。外部判例集はベンダー提供でカバー率が低く更新も遅い。監督指針はPDFを手動取り込みしている。過去回答の根拠を後から正確に再現できるかは、源ごとにまったく異なる。","評価（eval）データセットにも偏りがあった。既存の評価セットは過去に人手で「合格」とされた標準的な給付事例が中心で、免責判定や稀少な特約が絡む難ケースの比率が低い。このため、平均的な指標は良く見えても、規制上重い誤り（旧版参照・無根拠の判例）を捕捉しにくい。v1.3ではこの弱点が表面化した。","モデル更新v1.3は引用一致率と免責判定の正答を改善した一方で、幻覚率・最新約款の版整合率・平均レイテンシが悪化する回帰を伴った。月次KPIでもグラウンディング率は上がったのに幻覚率とレイテンシが同時に悪化しており、単一指標での合否判断が危ういことを示している。","経営会議は数日後に迫っている。限られた予算とレイテンシSLAの制約下で、当局説明責任・回帰是正・ROIのどれをどの順で満たすか、意思決定が求められている。あなたはAIエージェント・ストラテジストとして、複数の資料を横断し、制約の優先順位とトレードオフを踏まえた助言をしなければならない。"],"en":["Solphia P&C Insurance has rolled out 'LexGround,' a RAG (retrieval-augmented generation) assistant supporting benefit adjudication and policy-clause lookup, to 400 adjusters. LexGround cites the policy-clause DB, an internal FAQ, an external case-law collection, regulatory guidance, and a past-answer log as evidence, presenting adjusters with a draft reply and supporting links. Management set 'shorter handling time per case' and 'consistent explanation quality via evidence citation' as goals and is pushing hard for ROI within the fiscal year.","In June two serious incidents occurred in succession. One (I-105) presented a non-existent precedent as evidence and implied an exclusion; Compliance judged that a report to the regulator was required. The other (I-102) cited an exclusion clause from a superseded, pre-revision policy as if it were current, requiring customer notification. Legal stressed that 'the real problem is not the error itself but the inability to reconstruct and explain afterward why that evidence was presented.'","Stakeholder demands conflict. Management values the improved grounding rate and wants immediate company-wide rollout of the updated model v1.3 and ROI recovery. Legal and Compliance put version-consistency of evidence and auditability (reproducing who was shown which version as evidence) first. Front-line adjusters dislike the worsened response latency and rework of drafts. The data team argues that poor version control of the evidence sources is the true root cause, but remediation needs resources and time.","Readiness of the evidence sources varies widely. The policy-clause DB is managed by version number and date and keeps audit logs, whereas the internal FAQ is overwritten with no version retained and no audit log. The external case-law collection is vendor-provided with low coverage and slow updates. Regulatory guidance is manually ingested from PDFs. Whether the evidence behind a past answer can be reproduced accurately later differs completely by source.","The evaluation (eval) dataset was also biased. The existing set centers on standard benefit cases previously marked 'pass' by humans, with a low proportion of hard cases involving exclusion decisions or rare riders. As a result, average metrics look good but regulatorily severe errors (old-version references, unfounded precedents) are hard to catch. v1.3 exposed this weakness.","The v1.3 update improved citation-match and exclusion-decision accuracy, but came with a regression that worsened the hallucination rate, the latest-clause version-consistency rate, and average latency. Monthly KPIs also show the grounding rate rose while hallucination and latency worsened at the same time, showing that pass/fail judgments on a single metric are dangerous.","The management meeting is a few days away. Under a limited budget and a latency SLA, a decision is required on the order in which to satisfy regulatory accountability, regression remediation, and ROI. As an AI agent strategist you must cross-reference multiple materials and advise based on the priority of constraints and their trade-offs."]},"tables":[{"title":{"ja":"表1: 評価タスクと結果 vs 判定基準","en":"Table 1: Eval tasks and results vs. acceptance criteria"},"headers":{"ja":["タスクID","評価項目","目標基準","v1.2実測","v1.3実測","v1.3判定"],"en":["Task ID","Metric","Target","v1.2","v1.3","v1.3 result"]},"rows":{"ja":[["E-01","引用一致率","≥95%","96.2%","97.1%","合格"],["E-02","幻覚率（無根拠生成）","≤2.0%","1.8%","2.6%","不合格"],["E-03","最新約款の版整合率","≥98%","98.5%","94.0%","不合格"],["E-04","免責判定の正答率","≥90%","91.0%","92.3%","合格"],["E-05","平均応答レイテンシ","≤3.0秒","2.7秒","3.4秒","不合格"]],"en":[["E-01","Citation-match rate","≥95%","96.2%","97.1%","Pass"],["E-02","Hallucination rate (ungrounded)","≤2.0%","1.8%","2.6%","Fail"],["E-03","Latest-clause version consistency","≥98%","98.5%","94.0%","Fail"],["E-04","Exclusion-decision accuracy","≥90%","91.0%","92.3%","Pass"],["E-05","Avg. response latency","≤3.0s","2.7s","3.4s","Fail"]]}},{"title":{"ja":"表2: インシデント記録","en":"Table 2: Incident log"},"headers":{"ja":["事案ID","発生日","種別","影響区分","根拠版ズレ","是正状態"],"en":["Incident ID","Date","Type","Impact tier","Version mismatch","Status"]},"rows":{"ja":[["I-101","06-02","無根拠の給付可否回答","顧客通知要","有","是正済"],["I-102","06-09","旧約款の免責条項を引用","顧客通知要","有","対応中"],["I-103","06-15","出典リンク切れ","内部のみ","無","是正済"],["I-104","06-21","過大な支払額を提示","顧客通知要","無","対応中"],["I-105","06-28","存在しない判例を引用","監督当局報告要","有","対応中"],["I-106","07-03","出典の版が古い","内部のみ","有","是正済"]],"en":[["I-101","06-02","Ungrounded benefit-eligibility answer","Customer notice","Yes","Fixed"],["I-102","06-09","Cited superseded exclusion clause","Customer notice","Yes","In progress"],["I-103","06-15","Broken source link","Internal only","No","Fixed"],["I-104","06-21","Presented excessive payout amount","Customer notice","No","In progress"],["I-105","06-28","Cited a non-existent precedent","Regulator report","Yes","In progress"],["I-106","07-03","Stale source version","Internal only","Yes","Fixed"]]}},{"title":{"ja":"表3: 根拠データ源と整備度","en":"Table 3: Evidence sources and readiness"},"headers":{"ja":["データ源","版管理方式","最終更新","カバー率","監査ログ"],"en":["Source","Version control","Last update","Coverage","Audit log"]},"rows":{"ja":[["約款DB","版番号+日付","2026-06","100%","有"],["社内FAQ","上書き（版なし）","2026-05","80%","無"],["外部判例集","ベンダー提供","2026-01","60%","一部"],["監督指針","PDF手動取込","2026-03","90%","無"],["過去回答ログ","追記のみ","2026-07","70%","有"]],"en":[["Policy-clause DB","Version no. + date","2026-06","100%","Yes"],["Internal FAQ","Overwrite (no version)","2026-05","80%","No"],["External case-law","Vendor-provided","2026-01","60%","Partial"],["Regulatory guidance","Manual PDF ingest","2026-03","90%","No"],["Past-answer log","Append-only","2026-07","70%","Yes"]]}},{"title":{"ja":"表4: 月次KPI推移","en":"Table 4: Monthly KPI trend"},"headers":{"ja":["月","グラウンディング率","幻覚率","平均レイテンシ(秒)","月間クエリ数"],"en":["Month","Grounding rate","Hallucination rate","Avg latency (s)","Monthly queries"]},"rows":{"ja":[["2026-03","93.0%","1.9%","2.6","42,000"],["2026-04","94.5%","1.7%","2.7","45,000"],["2026-05","95.2%","1.6%","2.8","48,000"],["2026-06 (v1.3)","96.8%","2.5%","3.4","52,000"],["2026-07","96.5%","2.4%","3.3","55,000"]],"en":[["2026-03","93.0%","1.9%","2.6","42,000"],["2026-04","94.5%","1.7%","2.7","45,000"],["2026-05","95.2%","1.6%","2.8","48,000"],["2026-06 (v1.3)","96.8%","2.5%","3.4","52,000"],["2026-07","96.5%","2.4%","3.3","55,000"]]}},{"title":{"ja":"表5: ROI前提（月次）","en":"Table 5: ROI assumptions (monthly)"},"headers":{"ja":["項目","現状(人手)","導入後(想定)","備考"],"en":["Item","Current (manual)","After (assumed)","Note"]},"rows":{"ja":[["1件あたり人件費","600円","200円","差分400円/件"],["月間処理件数","55,000件","55,000件","表4の最新月"],["AI運用コスト","—","480万円","推論+保守/月"],["顧客通知要件数","—","40件","想定/月"],["幻覚是正コスト","—","25,000円/件","通知要1件あたり"]],"en":[["Labor cost per case","JPY 600","JPY 200","Delta JPY 400/case"],["Monthly cases","55,000","55,000","Latest month, Table 4"],["AI running cost","—","JPY 4.8M","Inference+maint./mo"],["Customer-notice cases","—","40","Assumed/mo"],["Remediation cost","—","JPY 25,000/case","Per notice case"]]}}],"questions":[{"n":1,"q":{"ja":"表1で、v1.3が判定基準から外れた不合格タスクのうち、基準値に対する相対乖離が最も大きいのはどれか。","en":"In Table 1, among the failing v1.3 tasks, which has the largest relative deviation from its target?"},"options":[{"label":{"ja":"E-02（幻覚率）で、基準比の相対乖離は約30%","en":"E-02 (hallucination), ~30% relative deviation"},"ok":true,"exp":{"ja":"(2.6−2.0)/2.0=0.30。E-03は(98−94)/98≈4.1%、E-05は(3.4−3.0)/3.0≈13.3%。相対乖離ではE-02が最大。","en":"(2.6−2.0)/2.0=0.30. E-03 is (98−94)/98≈4.1%, E-05 is (3.4−3.0)/3.0≈13.3%. E-02 is largest in relative terms."}},{"label":{"ja":"E-03（版整合率）で、絶対差4ポイントが不合格中で最大","en":"E-03 (version consistency), 4-point absolute gap is largest among failures"},"ok":false,"exp":{"ja":"絶対差4ポイントは大きく見えるが、設問は相対乖離。4/98≈4.1%でE-02の30%に遠く及ばない。絶対値と相対値の取り違え。","en":"The 4-point absolute gap looks big, but the question asks for relative deviation: 4/98≈4.1%, far below E-02's 30%. It confuses absolute with relative."}},{"label":{"ja":"E-05（レイテンシ）で、超過0.4秒が最も重い","en":"E-05 (latency), the 0.4s overage is heaviest"},"ok":false,"exp":{"ja":"0.4/3.0≈13.3%で二番目。体感上重くても相対乖離ではE-02が上回る。","en":"0.4/3.0≈13.3%, second place. However bad it feels, E-02 exceeds it in relative deviation."}},{"label":{"ja":"E-01（引用一致率）で、基準を下回り乖離最大","en":"E-01 (citation match), below target with largest deviation"},"ok":false,"exp":{"ja":"E-01は97.1%で基準95%を満たし合格。そもそも不合格タスクではない事実誤認。","en":"E-01 is 97.1% and passes the 95% target. It is not a failing task at all—a factual misread."}}]},{"n":2,"q":{"ja":"表2で、影響区分が『監督当局報告要』または『顧客通知要』で、かつ根拠版ズレが『有』の事案は何件か。","en":"In Table 2, how many incidents are tiered 'Regulator report' or 'Customer notice' AND have version mismatch 'Yes'?"},"options":[{"label":{"ja":"2件（I-101・I-102のみ該当）","en":"2 (only I-101, I-102)"},"ok":false,"exp":{"ja":"I-105（監督当局報告要・版ズレ有）を数え落としている。区分を顧客通知要だけに限定した誤り。","en":"Misses I-105 (Regulator report, mismatch Yes). Wrongly limits the tier to customer-notice only."}},{"label":{"ja":"3件（I-101・I-102・I-105が該当）","en":"3 (I-101, I-102, I-105)"},"ok":true,"exp":{"ja":"I-101(通知要,有)・I-102(通知要,有)・I-105(当局報告要,有)の3件。I-104は版ズレ無、I-106は内部のみで除外。","en":"I-101 (notice,Yes), I-102 (notice,Yes), I-105 (report,Yes) = 3. I-104 has no mismatch; I-106 is internal-only, both excluded."}},{"label":{"ja":"4件（版ズレ有の事案をすべて数え内部のみも含める）","en":"4 (count all mismatch-Yes incidents, including internal-only)"},"ok":false,"exp":{"ja":"版ズレ有はI-101/102/105/106の4件だが、I-106は『内部のみ』で影響区分の条件を満たさない。区分条件を無視した過大計上。","en":"Mismatch-Yes are I-101/102/105/106 (4), but I-106 is 'Internal only' and fails the tier condition. Over-counts by ignoring the tier filter."}},{"label":{"ja":"1件（当局報告要のI-105だけを数える）","en":"1 (count only I-105 with the regulator-report tier)"},"ok":false,"exp":{"ja":"『または』条件を『当局報告要のみ』と読み違えている。顧客通知要かつ版ズレ有のI-101・I-102を除外した誤り。","en":"Misreads the 'or' condition as 'regulator report only,' dropping I-101/I-102 which meet notice AND mismatch."}}]},{"n":3,"q":{"ja":"表4の最新月クエリ数と表5の前提から、月間の純便益（人件費削減−AI運用コスト−幻覚是正コスト）を求め、回収可否を判定せよ。","en":"Using the latest-month queries in Table 4 and Table 5 assumptions, compute monthly net benefit (labor savings − AI running cost − remediation cost) and judge recovery."},"options":[{"label":{"ja":"約1,720万円の純便益（是正コスト未計上）","en":"~JPY 17.2M net (remediation cost omitted)"},"ok":false,"exp":{"ja":"2,200万−480万=1,720万は幻覚是正コスト100万を差し引き忘れた過大評価。","en":"22M−4.8M=17.2M forgets to subtract the 1M remediation cost; an overestimate."}},{"label":{"ja":"約1,620万円の純便益で回収は成立","en":"~JPY 16.2M net; recovery holds"},"ok":true,"exp":{"ja":"削減400円×55,000件=2,200万。−運用480万−是正(40件×25,000=100万)=1,620万の黒字で回収成立。","en":"400×55,000=22M savings. −4.8M running −(40×25,000=1M) remediation = 16.2M positive; recovery holds."}},{"label":{"ja":"約2,100万円の純便益（運用コスト未控除）","en":"~JPY 21.0M net (running cost not deducted)"},"ok":false,"exp":{"ja":"2,200万−是正100万=2,100万は、月480万のAI運用コストを控除し忘れた誤り。","en":"22M−1M=21M forgets to deduct the JPY 4.8M/mo AI running cost."}},{"label":{"ja":"回収不成立（運用コストが削減額を上回る）","en":"No recovery (running cost exceeds savings)"},"ok":false,"exp":{"ja":"削減2,200万に対し運用480万は下回り、純便益は正。回収不成立は前提の誤読。","en":"Running 4.8M is well below 22M savings, so net is positive. 'No recovery' misreads the assumptions."}}]},{"n":4,"q":{"ja":"v1.3で改善した指標もある中、規制説明責任の観点から最も重大な回帰はどれか。","en":"Although v1.3 improved some metrics, which regression is most serious from a regulatory-accountability standpoint?"},"options":[{"label":{"ja":"E-03の版整合回帰で、旧約款を提示する恐れ","en":"E-03 version-consistency regression risks citing old clauses"},"ok":true,"exp":{"ja":"版整合が98.5→94.0%に低下。旧約款を最新と誤提示すれば顧客・当局への説明責任を直接損なう（I-102型）。説明責任が最優先制約なら最重大。","en":"Version consistency fell 98.5→94.0%. Presenting old clauses as current directly harms accountability to customers and the regulator (I-102 type). Most serious when accountability is the top constraint."}},{"label":{"ja":"E-02の幻覚率が基準を超過し、相対乖離も最大となるため","en":"E-02 hallucination exceeds target and has the largest relative deviation"},"ok":false,"exp":{"ja":"相対乖離は最大だが、幻覚は検知・遮断しやすい。設問は説明責任の観点。版を誤って根拠提示する回帰の方が事後説明を崩す。","en":"Its relative deviation is largest, but hallucinations are easier to detect/block. The question is about accountability, where mis-versioned evidence more directly breaks after-the-fact explanation."}},{"label":{"ja":"E-05のレイテンシ超過で、現場SLAを外すため","en":"E-05 latency overage misses the front-line SLA"},"ok":false,"exp":{"ja":"レイテンシは現場体験・SLAの問題で、規制説明責任には直結しない。制約軸を取り違えている。","en":"Latency is a UX/SLA concern, not directly regulatory accountability. It targets the wrong constraint axis."}},{"label":{"ja":"E-01は改善しており、回帰は実質発生していない","en":"E-01 improved, so no regression really occurred"},"ok":false,"exp":{"ja":"E-01改善は事実だが、E-02/E-03/E-05は明確に回帰。単一指標で全体を判断する典型的誤り。","en":"E-01 did improve, but E-02/E-03/E-05 clearly regressed. Judging the whole by one metric is the classic error."}}]},{"n":5,"q":{"ja":"過去回答の提示根拠を監査で再現する上で、表3のうち最も是正優先度が高いデータ源はどれか。","en":"For reproducing the evidence shown in past answers during an audit, which Table 3 source has the highest remediation priority?"},"options":[{"label":{"ja":"社内FAQ（版管理なし・監査ログ無で再現不可）","en":"Internal FAQ (no versioning, no audit log; unreproducible)"},"ok":true,"exp":{"ja":"上書き更新で版が残らず監査ログも無いため、過去にどの内容を根拠提示したかを事後に再現できない。説明責任・監査の観点で是正優先度が最も高い。","en":"Overwritten with no version retained and no audit log, so what was shown as evidence in the past cannot be reproduced. Highest priority for accountability/audit."}},{"label":{"ja":"外部判例集（カバー率60%で最も低いため）","en":"External case-law (lowest coverage at 60%)"},"ok":false,"exp":{"ja":"カバー率は低いがベンダー提供で版は追跡でき監査は一部可能。設問は再現性であり、版が残らないFAQの方が監査上致命的。","en":"Coverage is low but the vendor provides trackable versions with partial audit. The question is reproducibility, where the version-less FAQ is more fatal."}},{"label":{"ja":"約款DB（月間更新でズレが起きやすいため）","en":"Policy-clause DB (monthly updates make drift likely)"},"ok":false,"exp":{"ja":"約款DBは版番号+日付+監査ログが揃い、再現性は最も高い。更新頻度は運用課題であって監査再現不可の源ではない。","en":"The DB has version+date+audit log and the best reproducibility. Update frequency is an ops concern, not an audit-reproducibility failure."}},{"label":{"ja":"過去回答ログ（追記のみで改ざん検知できないため）","en":"Past-answer log (append-only, so tampering cannot be detected)"},"ok":false,"exp":{"ja":"追記のみは改ざん耐性が高く監査ログも有で、むしろ再現に資する。『改ざん検知できない』は追記型の性質の誤解。","en":"Append-only is tamper-resistant and has an audit log, aiding reproduction. 'Cannot detect tampering' misreads what append-only means."}}]},{"n":6,"q":{"ja":"説明責任を最優先制約とし、当局報告要インシデントが発生している状況で、次に着手すべきアクションはどれか。","en":"With accountability as the top constraint and a regulator-reportable incident open, which action should be taken next?"},"options":[{"label":{"ja":"現場のレイテンシを最優先で改善し利用率を上げる","en":"Fix front-line latency first to raise adoption"},"ok":false,"exp":{"ja":"レイテンシは重要だが説明責任より下位。当局報告要（I-105）と版整合回帰を放置したまま利用を促すのは制約順位を外す。","en":"Latency matters but ranks below accountability. Driving adoption while leaving the reportable incident and version regression unaddressed misorders the constraints."}},{"label":{"ja":"版整合の回帰是正と監査ログ整備を先行させる","en":"Prioritize fixing the version regression and audit logging"},"ok":true,"exp":{"ja":"E-03回帰の是正で旧約款提示を止め、版なしFAQ等の監査ログを整えれば、当局・顧客への根拠再現と説明が可能になる。最優先制約に直結。","en":"Fixing the E-03 regression stops old-clause citations, and adding audit logs (e.g., the version-less FAQ) enables reproducing evidence for regulator and customers. Directly serves the top constraint."}},{"label":{"ja":"グラウンディング率は基準達成のため展開を継続する","en":"Grounding rate meets target, so continue the rollout"},"ok":false,"exp":{"ja":"グラウンディング率が高くても幻覚率・版整合は回帰し当局報告要が発生済み。単一指標を根拠に展開継続は説明責任を軽視する。","en":"Even with a high grounding rate, hallucination and version consistency regressed and a reportable incident exists. Continuing on one metric slights accountability."}},{"label":{"ja":"ROIが大きいためv1.3を全社へ即時展開し様子を見る","en":"ROI is large, so roll v1.3 out company-wide now and watch"},"ok":false,"exp":{"ja":"純便益は正だが、回帰未是正のまま拡大すれば当局報告要インシデントを増幅する。ROIは説明責任・回帰是正の後に位置づくべき。","en":"Net benefit is positive, but scaling before fixing the regression amplifies reportable incidents. ROI should rank after accountability and remediation."}}]}]}];

// ExamCaseRunner — 本試験形式のケース（複数ケース選択＋共有ケース本文＋資料表＋僅差4択＋根拠解説）
function ExamCaseRunner({ cases, lang, onBack, backRef, ck }) {
  const caseDone = useDoneSet("case:" + (ck || "x"));
  const g = (o) => (o && (o[lang] != null ? o[lang] : o.ja));
  const clist = Array.isArray(cases) ? cases : [cases];
  const [pick, setPick] = useState(clist.length === 1 ? 0 : null);
  const [qi, setQi] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);

  const th = { textAlign: "left", padding: "7px 9px", background: "#EDE9E0", color: C.deep, fontSize: 11.5, fontWeight: 700, borderBottom: `1px solid ${C.mid}`, whiteSpace: "nowrap" };
  const td = { padding: "7px 9px", fontSize: 12, borderBottom: `1px solid ${C.mid}`, verticalAlign: "top", lineHeight: 1.45 };

  const openCase = (i) => { setPick(i); setQi(0); setAnswers({}); setFinished(false); };
  useEffect(() => { if (!backRef) return; backRef.current = () => { if (pick !== null && clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); return true; } return false; }; return () => { if (backRef) backRef.current = null; }; }, [pick, backRef]);
  const backToList = () => { if (clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); } else onBack(); };

  if (pick === null) {
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <button onClick={onBack} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{lang === "ja" ? "← 戻る" : "← Back"}</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 4 }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style cases"}</div>
        <div style={{ fontSize: 12, color: "#5d6c83", marginBottom: 12 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "Data tables, 4 close options, rationale for each"}</div>
        {clist.map((c, i) => (
          <button key={i} onClick={() => openCase(i)}
            style={{ width: "100%", textAlign: "left", padding: "14px 15px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5, color: C.deep, lineHeight: 1.45, paddingRight: 10 }}><DoneCheck on={caseDone.has(i)} onToggle={(e) => caseDone.toggle(i, e)} />{g(c.title)}</span>
            <span style={{ fontSize: 11.5, color: "#5d6c83", whiteSpace: "nowrap" }}>{c.questions.length}{lang === "ja" ? "問" : "Q"}</span>
          </button>
        ))}
      </div>
    );
  }

  const data = clist[pick];
  const qs = data.questions;
  const Q = qs[qi];
  const sel = answers[qi] != null ? answers[qi] : null;
  const choose = (i) => { if (sel !== null) return; setAnswers(a => ({ ...a, [qi]: i })); };
  const prev = () => { if (qi > 0) setQi(qi - 1); };
  const next = () => { if (qi < qs.length - 1) setQi(qi + 1); };
  const restart = () => { setQi(0); setAnswers({}); setFinished(false); };

  let correct = 0;
  for (let k = 0; k < qs.length; k++) { const a = answers[k]; if (a != null && qs[k].options[a] && qs[k].options[a].ok) correct++; }
  const answeredCount = Object.keys(answers).length;
  const rate = qs.length ? Math.round((correct / qs.length) * 100) : 0;

  const navBtn = (label, onClick, enabled, primary) => (
    <button onClick={enabled ? onClick : undefined} disabled={!enabled}
      style={{ flex: 1, padding: "11px 12px", borderRadius: 9, fontSize: 13.5, fontWeight: 700,
        cursor: enabled ? "pointer" : "default",
        border: primary ? "none" : `1.5px solid ${enabled ? C.primary : C.mid}`,
        background: primary ? (enabled ? C.primary : C.mid) : "#fff",
        color: primary ? "#fff" : (enabled ? C.primary : "#b9c4d6") }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={backToList} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{clist.length > 1 ? (lang === "ja" ? "← ケース一覧" : "← Case list") : (lang === "ja" ? "← 戻る" : "← Back")}</button>
        {!finished && <span style={{ fontSize: 12, color: "#5d6c83" }}>{lang === "ja" ? `問 ${qi + 1} / ${qs.length}` : `Q ${qi + 1} / ${qs.length}`}</span>}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 12 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 10 }}>{g(data.title)}</div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 6 }}>{lang === "ja" ? "ケース本文（資料）" : "Case (materials)"}</div>
        {g(data.body).map((p, i) => (<div key={i} style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 8, color: C.ink }}>{p}</div>))}
        {(data.tables || []).map((tb, ti) => (
          <div key={ti} style={{ marginTop: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{g(tb.title)}</div>
            <div style={{ overflowX: "auto", border: `1px solid ${C.mid}`, borderRadius: 8 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320 }}>
                <thead><tr>{g(tb.headers).map((h, hi) => (<th key={hi} style={th}>{h}</th>))}</tr></thead>
                <tbody>{g(tb.rows).map((r, ri) => (<tr key={ri}>{r.map((cell, ci) => (<td key={ci} style={td}>{cell}</td>))}</tr>))}</tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {finished ? (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ textAlign: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "ケース完了" : "Case complete"}</div>
            <div style={{ fontSize: 32, fontWeight: 800, color: rate >= PASS ? C.ok : C.ng }}>{rate}%</div>
            <div style={{ fontSize: 12.5, color: "#5d6c83", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${qs.length} 問` : `${correct} / ${qs.length} correct`}</div>
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
          <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
            <button onClick={() => { setFinished(false); setQi(0); }} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "解答を見直す" : "Review answers"}</button>
            <button onClick={restart} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "もう一度" : "Retry"}</button>
          </div>
        </div>
      ) : (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{lang === "ja" ? `問${Q.n}. ` : `Q${Q.n}. `}{g(Q.q)}</div>
          {Q.options.map((opt, i) => {
            let bg = "#fff", bd = C.mid, col = C.ink;
            if (sel !== null) { if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
            return (
              <button key={i} onClick={() => choose(i)} disabled={sel !== null}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.5, fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && opt.ok ? "✓" : sel !== null && i === sel ? "✗" : "ABCD"[i]}</span>{g(opt.label)}
              </button>
            );
          })}
          {sel !== null && (
            <div style={{ marginTop: 12 }}>
              {Q.options.map((opt, i) => (
                <div key={i} style={{ background: opt.ok ? "#E6F4EC" : (i === sel ? "#FBEAE8" : C.light), borderRadius: 8, padding: "9px 11px", marginBottom: 6, fontSize: 12.5, lineHeight: 1.55 }}>
                  <span style={{ fontWeight: 700, marginRight: 6, color: opt.ok ? C.ok : (i === sel ? C.ng : "#5d6c83") }}>{"ABCD"[i]}{opt.ok ? (lang === "ja" ? "（正解）" : " (correct)") : ""}</span>{g(opt.exp)}
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            {navBtn(lang === "ja" ? "← 前の問題" : "← Previous", prev, qi > 0, false)}
            {qi < qs.length - 1
              ? navBtn(lang === "ja" ? "次の問題 →" : "Next →", next, sel !== null, true)
              : navBtn(lang === "ja" ? "結果を見る →" : "See result →", () => setFinished(true), answeredCount === qs.length, true)}
          </div>
        </div>
      )}
    </div>
  );
}

function CaseStudy({ onAnswer, lang }) {
  const t = UI[lang];
  const [setNo, setSetNo] = useState(null);
  const [orderMode, setOrderMode] = useState("fixed");
  const [sessionList, setSessionList] = useState([]);
  const [showExam, setShowExam] = useState(false);
  const list = sessionList;
  const [idx, setIdx] = useState(0);
  const [sel, setSel] = useState(null);
  const labels = CASE_LABELS[lang];

  if (showExam) return <ExamCaseRunner ck="AICX_EXAM_CASES" cases={AICX_EXAM_CASES} lang={lang} onBack={() => setShowExam(false)} />;

  const start = (n) => {
    const base = CASE_SETS[n];
    setSessionList(orderMode === "random" ? shuffle(base) : base);
    setSetNo(n); setIdx(0); setSel(null);
  };

  if (!setNo) {
    return (
      <div>
        <Card title={t.caseTitle}>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#475569", marginBottom: 10 }}>{t.caseDesc}</div>
          <div style={{ display: "flex", justifyContent: "center" }}>
            <div style={{ display: "inline-flex", background: "#EDE9E0", borderRadius: 999, padding: 3 }}>
              {[["fixed", t.fixed], ["random", t.random]].map(([k, lbl]) => (
                <button key={k} onClick={() => setOrderMode(k)}
                  style={{ border: "none", cursor: "pointer", borderRadius: 999, padding: "6px 18px", fontSize: 12.5, fontWeight: 700,
                    background: orderMode === k ? "#fff" : "transparent", color: orderMode === k ? nvInk(C.deep, "#ffffff") : nvInk("#8a8275", C.mid),
                    boxShadow: orderMode === k ? "0 1px 2px rgba(0,0,0,0.08)" : "none" }}>
                  {lbl}
                </button>
              ))}
            </div>
          </div>
        </Card>
        <button onClick={() => setShowExam(true)}
          style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
            border: `1.5px solid ${C.deep}`, background: "#FBF7EF", cursor: "pointer",
            display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span>
            <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style case"}</span>
            <span style={{ fontSize: 12, color: "#5a6a85", marginLeft: 8 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "With data tables, 4 close options, rationale for each"}</span>
          </span>
          <span style={{ fontSize: 12.5, fontWeight: 700, color: C.deep }}>{lang === "ja" ? "挑戦 →" : "Start →"}</span>
        </button>
        {[1, 2, 3, 4, 5].map(n => {
          const ready = CASE_SETS[n].length > 0;
          return (
            <button key={n} onClick={() => ready && start(n)} disabled={!ready}
              style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
                border: `1.5px solid ${ready ? C.primary : C.mid}`, background: ready ? "#fff" : C.light,
                cursor: ready ? "pointer" : "not-allowed", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span>
                <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{t.set} {n}</span>
                <span style={{ fontSize: 12, color: "#5a6a85", marginLeft: 8 }}>{labels[n]}</span>
                <span style={{ fontSize: 12, color: "#5d6c83", marginLeft: 8 }}>{CASE_SETS[n].length > 0 ? `${CASE_SETS[n].length}${t.questions}` : t.preparing}</span>
              </span>
              {ready && <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary }}>{t.start}</span>}
            </button>
          );
        })}
      </div>
    );
  }

  if (list.length === 0) return <div style={{ textAlign: "center", color: "#5d6c83", padding: 20 }}>{t.preparing}</div>;
  const raw = list[idx % list.length];
  const seq = idx % list.length;
  const c = { d: raw.d, ...pickCase(raw.ja, raw.en, lang, seq) };
  const cJa = pickCase(raw.ja, raw.en, "ja", seq);
  const cEn = pickCase(raw.ja, raw.en, "en", seq);
  const choose = (i) => { if (sel !== null) return; setSel(i); onAnswer(c.d, c.options[i].ok, normReviewCase(cJa, cEn), "case"); };
  const next = () => { setSel(null); setIdx(i => i + 1); };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={() => setSetNo(null)} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{t.toSetSelectShort}</button>
        <span style={{ fontSize: 12, color: "#5d6c83" }}>{t.set}{setNo} · {t.caseCount((idx % list.length) + 1, list.length)}</span>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[c.d]), background: DOM_HUE[c.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{c.d} · {t.domainNames[c.d]}</div>
        <div style={{ background: C.light, borderRadius: 9, padding: 12, marginBottom: 12 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 4 }}>{t.situation}</div>
          <div style={{ fontSize: 13.5, lineHeight: 1.6 }}>{c.scene}</div>
        </div>
        <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{c.q}</div>
        {c.options.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px",
                borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col,
                cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.4,
                fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && (opt.ok) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt.label}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: c.options[sel].ok ? "#E6F4EC" : "#FBEAE8", borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>{c.options[sel].fb}</div>
            <div style={{ marginTop: 10, display: "flex", gap: 10, flexWrap: "wrap" }}>
              <div style={{ flex: "1 1 45%", background: "#fff", border: `1.5px solid ${C.mid}`, borderRadius: 9, padding: "10px 12px" }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 3 }}>{t.axis}</div>
                <div style={{ fontSize: 12.5, lineHeight: 1.4 }}>{c.axis}</div>
              </div>
              <div style={{ flex: "1 1 45%", background: "#fff", border: `1.5px solid ${C.mid}`, borderRadius: 9, padding: "10px 12px" }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 3 }}>{t.point}</div>
                <div style={{ fontSize: 12.5, lineHeight: 1.4 }}>{c.point}</div>
              </div>
            </div>
            <button onClick={next}
              style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
              {(idx % list.length) + 1 >= list.length ? t.firstCase : t.nextCase}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function Review({ state, onAnswer, clearReview, removeReview, lang }) {
  const t = UI[lang];
  const review = state.review || [];
  const [domFilter, setDomFilter] = useState("ALL");
  const srcMeta = [{ key: "exam", label: t.srcExam }, { key: "case", label: t.srcCase }];

  if (review.length === 0) {
    return <Card title={t.reviewTitle}><div style={{ fontSize: 13, color: "#5a6a85", lineHeight: 1.6 }}>{t.reviewEmpty}</div></Card>;
  }
  const filtered = domFilter === "ALL" ? review : review.filter(r => r.d === domFilter);

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.deep }}>{t.wrongCount(review.length)}</div>
        <button onClick={clearReview} style={{ padding: "5px 12px", borderRadius: 8, fontSize: 12, fontWeight: 700, border: `1.5px solid ${C.mid}`, background: "#fff", color: "#5d6c83", cursor: "pointer" }}>{t.clearAll}</button>
      </div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
        {[["ALL", t.allDomains], ...DOMAINS.map(d => [d.id, d.id])].map(([k, lbl]) => (
          <button key={k} onClick={() => setDomFilter(k)}
            style={{ padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer",
              border: `1px solid ${domFilter === k ? C.primary : C.mid}`,
              background: domFilter === k ? C.primary : "#fff", color: domFilter === k ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600 }}>
            {lbl}
          </button>
        ))}
      </div>
      {srcMeta.map(({ key, label }) => {
        const items = filtered.filter(r => r.src === key);
        if (items.length === 0) return null;
        return (
          <div key={key} style={{ marginBottom: 22 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, paddingBottom: 6, borderBottom: `2px solid ${C.mid}` }}>
              <span style={{ fontSize: 15, fontWeight: 800, color: C.deep }}>{label}</span>
              <span style={{ fontSize: 12, color: nvInk("#ffffff", C.primary), background: C.primary, borderRadius: 12, padding: "1px 9px", fontWeight: 700 }}>{items.length}</span>
            </div>
            {items.map(r => <ReviewCard key={r.key} rec={r} onAnswer={onAnswer} removeReview={removeReview} lang={lang} />)}
          </div>
        );
      })}
      {filtered.length === 0 && <div style={{ textAlign: "center", color: "#5d6c83", padding: 20 }}>{t.noWrongInDomain}</div>}
    </div>
  );
}

function ReviewCard({ rec, onAnswer, removeReview, lang }) {
  const t = UI[lang];
  const [sel, setSel] = useState(null);
  const it = (rec.item && rec.item[lang]) ? rec.item[lang] : (rec.item.ja || rec.item);
  const opts = it.options.map(o => o.label);
  const answerIdx = it.options.findIndex(o => o.ok);
  const choose = (i) => { if (sel !== null) return; setSel(i); onAnswer(rec.d, it.options[i].ok, rec.item, rec.src); };

  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 15, marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        <span style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[rec.d]), background: DOM_HUE[rec.d], borderRadius: 4, padding: "2px 8px" }}>{rec.d} · {t.domainNames[rec.d]}</span>
        <button onClick={() => removeReview(rec.key)} style={{ border: "none", background: "none", color: "#b9c4d6", cursor: "pointer", fontSize: 18, lineHeight: 1, padding: 0 }}>×</button>
      </div>
      {it.scene && (
        <div style={{ background: C.light, borderRadius: 9, padding: 10, marginBottom: 10 }}>
          <div style={{ fontSize: 10.5, fontWeight: 700, color: C.primary, marginBottom: 3 }}>{t.situation}</div>
          <div style={{ fontSize: 12.5, lineHeight: 1.55 }}>{it.scene}</div>
        </div>
      )}
      <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 12, lineHeight: 1.5 }}>{it.q}</div>
      {opts.map((opt, i) => {
        let bg = "#fff", bd = C.mid, col = C.ink;
        if (sel !== null) {
          if (i === answerIdx) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; }
          else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
        }
        return (
          <button key={i} onClick={() => choose(i)} disabled={sel !== null}
            style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "10px 12px",
              borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col,
              cursor: sel === null ? "pointer" : "default", fontSize: 13, lineHeight: 1.4,
              fontWeight: sel !== null && i === answerIdx ? 700 : 500 }}>
            <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && (i === answerIdx) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
          </button>
        );
      })}
      {sel !== null && (
        <div>
          <div style={{ background: (sel === answerIdx) ? "#E6F4EC" : "#FBEAE8", borderRadius: 9, padding: 11, fontSize: 12.5, lineHeight: 1.55 }}>
            <strong style={{ color: nvInk(sel === answerIdx ? C.ok : C.ng, C.light) }}>{sel === answerIdx ? t.correct : t.incorrect}</strong>
            {t.answerIs("ABCD"[answerIdx])}{it.options[answerIdx].fb}
          </div>
          {sel === answerIdx && <div style={{ fontSize: 12, color: C.ok, fontWeight: 700, textAlign: "center", marginTop: 8 }}>{t.removedHint}</div>}
        </div>
      )}
    </div>
  );
}

function Compare({ lang }) {
  const t = UI[lang];
  const norm = (COMPARE || []).map((c) => ({
    title: c.title, titleEn: c.titleEn,
    axisJa: (c.head || [])[0], axisEn: ((c.headEn || c.head) || [])[0],
    cols: (c.head || []).slice(1), colsEn: ((c.headEn || c.head) || []).slice(1),
    rows: c.rows, rowsEn: c.rowsEn || c.rows,
  }));
  return <CmpTable compare={norm} C={C} lang={lang} t={{ compareSearch: t.searchCompare, noMatch: t.noMatch }} />;
}

function Confuse({ lang }) {
  const t = UI[lang];
  const [q, setQ] = useState("");
  const data = CONFUSE.map(c => lang === "en" && c[3] ? [c[3], c[4], c[5]] : [c[0], c[1], c[2]]);
  const list = data.filter(c => !q || c.join("").toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} aria-label={t.searchConfuse} placeholder={t.searchConfuse}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 14, boxSizing: "border-box" }} />
      {list.map((c, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 10 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 13.5, marginBottom: 5 }}>{c[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5, marginBottom: 4 }}>{c[1]}</div>
          <div style={{ fontSize: 12, color: C.primary, fontWeight: 600 }}>{t.judgeAxis}{c[2]}</div>
        </div>
      ))}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#5d6c83", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Glossary({ lang }) {
  const t = UI[lang];
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("ALL");
  const cats = ["ALL", ...DOMAINS.map(d => d.id)];
  const list = GLOSSARY.filter(g => {
    if (cat !== "ALL" && g[0] !== cat) return false;
    if (!q) return true;
    return (g[1] + g[2] + g[3] + (g[4] || "")).toLowerCase().includes(q.toLowerCase());
  });
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} aria-label={t.searchTerm} placeholder={t.searchTerm}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 10, boxSizing: "border-box" }} />
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>
        {cats.map(k => (
          <button key={k} onClick={() => setCat(k)}
            style={{ padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer", border: `1px solid ${cat === k ? C.primary : C.mid}`, background: cat === k ? C.primary : "#fff", color: cat === k ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600 }}>
            {k === "ALL" ? t.allDomains : k}
          </button>
        ))}
      </div>
      {list.map((g, i) => {
        const hasEn = g[2] && g[2] !== "-";
        const primary = lang === "en" && hasEn ? g[2] : g[1];
        const secondary = lang === "en" ? (hasEn ? g[1] : null) : (hasEn ? g[2] : null);
        const def = lang === "en" && g[4] ? g[4] : g[3];
        return (
          <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 9 }}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
              <span style={{ background: DOM_HUE[g[0]], color: nvInk("#ffffff", DOM_HUE[g[0]]), borderRadius: 4, padding: "1px 6px", fontSize: 10.5 }}>{g[0]}</span>
              <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{primary}</span>
              {secondary && <span style={{ fontSize: 11.5, color: "#5d6c83" }}>{secondary}</span>}
            </div>
            <div style={{ fontSize: 13, lineHeight: 1.5 }}>{def}</div>
          </div>
        );
      })}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#5d6c83", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

